/**
 * NUTVIQUE INVENTORY  –  master product, price and stock system for Nutzy Foods Pvt Ltd
 * ------------------------------------------------------------------------------------
 * Google Sheet + Apps Script web app (laptop + phone). Owner: nutzyfoods@gmail.com.
 *
 *  • Upload a supplier invoice (PDF / photo) → Gemini reads it → each line is matched to a
 *    Nutvique product (remembered seller names first) → landed cost, selling price and MRP
 *    side by side → Post: stock is booked into Central Warehouse, costs/prices updated.
 *  • New item on an invoice → suggested Nutvique name, SKU, HSN, prices → on confirm the next
 *    free GTIN is issued (never reused) and the item is queued for the GS1 DataKart and
 *    QueueBuster upload files.
 *  • Stock = this system's ledger + the Night Closing app's Stock Ledger (transfers, events…).
 *    Every movement made here is mirrored into the Night Closing ledger (Ref starts "INV-") and
 *    products / selling prices are pushed to its Products tab, so both apps always agree.
 *
 * Editor helpers (Run menu): setup, syncProductsToNightClosing, testGemini.
 */

// ───────────────────────────── constants ─────────────────────────────
const APP_NAME = 'Nutvique Inventory';
const NC_DEFAULT_ID = '1xoqDp8aPWngTCYEV7NH5B4FQKGfuJGIrN2o9S1GjVkI';   // Night Closing data sheet
const CENTRAL = 'Central Warehouse';
const LOCATIONS = [CENTRAL, 'Gulshan One29 Mall', 'City Galleria – Gaur City-2', 'Central Market – Sector 120'];
const MIRROR_PREFIX = 'INV-';           // refs of rows this app writes into the Night Closing ledger

const T = {                              // tab names
  products: 'Products', gtins: 'GTIN Register', invoices: 'Invoices', lines: 'Invoice Lines',
  ledger: 'Stock Ledger', prices: 'Price History', aliases: 'Seller Names', settings: 'Settings', log: 'Sync Log'
};
const H = {
  products: ['SKU', 'GTIN', 'Nutvique name', 'Seller names (as on invoices)', 'Short description', 'Category', 'Pack type',
    'Net content', 'Unit', 'HSN', 'GST %', 'Last cost ₹', 'Avg cost ₹', 'Selling price ₹', 'MRP ₹', 'Margin %', 'GS1 status',
    'Status', 'Reorder level', 'Last supplier', 'Last purchase', 'Notes', 'Created', 'Updated'],
  gtins: ['GTIN', 'SKU', 'Product', 'Issued on', 'Source'],
  invoices: ['Invoice ID', 'Status', 'Supplier', 'Supplier GSTIN', 'Invoice no.', 'Invoice date', 'Received at', 'Taxable ₹',
    'GST ₹', 'Other charges ₹', 'Round off ₹', 'Invoice total ₹', 'Total qty', 'Lines', 'New products', 'Stock added',
    'File', 'Notes', 'Saved by', 'Saved at', 'Posted at', 'Draft data'],
  lines: ['Invoice ID', 'Line', 'Seller item name', 'HSN', 'Invoice qty', 'Invoice unit', 'Rate excl. GST ₹', 'Amount ₹',
    'GST %', 'Charges share ₹', 'Landed total ₹', 'SKU', 'Nutvique name', 'Qty booked', 'Unit', 'Landed cost / unit ₹',
    'Selling price ₹', 'MRP ₹', 'Margin %', 'New product'],
  ledger: ['Date', 'Location', 'Movement', 'Product', 'SKU', 'Unit', 'Qty (+ in / − out)', 'Cost / unit ₹', 'Value ₹', 'Ref',
    'Party', 'Note', 'Entered by', 'Saved at'],
  prices: ['Saved at', 'SKU', 'Product', 'Old cost', 'New cost', 'Old selling', 'New selling', 'Old MRP', 'New MRP', 'Source', 'By'],
  aliases: ['Supplier', 'Seller item name', 'Match key', 'SKU', 'Nutvique name', 'Share of line', 'Last rate ₹', 'Last landed ₹',
    'Last invoice', 'Last date', 'Times'],
  settings: ['Setting', 'Value', 'Note'],
  log: ['Saved at', 'What', 'Result']
};
// Product column indexes (0-based) – keep in sync with H.products
const P = {}; H.products.forEach((h, i) => P[h] = i);
const PC = { sku: 0, gtin: 1, name: 2, seller: 3, short: 4, cat: 5, pack: 6, net: 7, unit: 8, hsn: 9, gst: 10, cost: 11, avg: 12,
  sell: 13, mrp: 14, margin: 15, gs1: 16, status: 17, reorder: 18, supplier: 19, lastBuy: 20, notes: 21, created: 22, updated: 23 };

const DEFAULT_SETTINGS = [
  ['Owner PIN', '', 'Full access: costs, invoices, new products, GS1, settings. Set on first open.'],
  ['Staff PIN', '', 'Price & stock check only (no cost prices). Leave blank to let anyone with the link check prices.'],
  ['Night Closing sheet ID', NC_DEFAULT_ID, 'Data sheet of the Night Closing app – stock movements are read from / mirrored to it.'],
  ['Gemini model', 'gemini-2.5-flash', 'Model that reads invoices. The API key is stored privately (Settings screen in the app).'],
  ['Markup (selling = cost ×)', 2, 'Suggested selling price for new products = landed cost × this, rounded up.'],
  ['Round selling price up to', 10, 'Suggested selling prices are rounded up to a multiple of this (₹).'],
  ['MRP = selling ×', 1.25, 'Same rule as QueueBuster (MRP = selling price × 1.25, rounded).'],
  ['Minimum margin %', 30, 'Warn when (selling − cost) ÷ selling is below this.'],
  ['Cost includes GST', 'No', 'No = GST is taken as input credit (cost = rate excl. GST + share of charges).'],
  ['Spread charges by', 'Value', 'Value or Quantity – how packing / freight on an invoice is shared between lines.'],
  ['Allow negative stock', 'Yes', 'Opening stock is not loaded yet, so negative quantities are allowed (shown in red).'],
  ['GS1 company prefix', '890622285', 'GTIN = prefix + 3-digit item number + check digit.'],
  ['Last GTIN used on DataKart', '', 'Only if DataKart issued GTINs that are not in GTIN Register. New GTINs start after the higher one.'],
  ['GS1 brand name', 'NUTVIQUE', ''],
  ['GS1 product channel', 'General Trade,Modern Trade,Ecommerce,Institutional Sale', 'DataKart accepts only its channel names.'],
  ['GS1 category', 'Food', ''], ['GS1 sub category', 'Dry Fruits/Seeds', ''],
  ['Website', 'www.nutvique.com', ''], ['Target market', 'India', ''], ['MRP location', 'Pan India', ''],
  ['Case type', 'NonStandardCase', ''], ['Country of origin', 'India', ''],
  ['Default height (cm)', 12, ''], ['Default width (cm)', 45, ''], ['Default depth (cm)', 32, ''],
  ['De-activation date', '2050-09-30', ''], ['Food type', 'Veg', ''], ['FSSAI licence no. (GS1)', '12726999000677', ''],
  ['Shelf life based on', 'Manufacturing Date', ''], ['Shelf life unit', 'Months', ''], ['Shelf life', 6, ''],
  ['Storage condition', 'Ambient', ''],
  ['QueueBuster brand', 'Nutvique', ''], ['QB: Price Includes Taxes', 'Yes', ''], ['QB: Manage Inventory', 'Yes', ''],
  ['QB: Stock Item Type', 'Unbatched', ''], ['QB: Is Sellable On POS', 'Yes', ''], ['QB: Allow variable pricing', 'No', ''],
  ['QB: Enable Low Stock Alert', 'No', ''],
  ['GS1 template file ID', '', 'Set from the app (More → Settings → upload template). Blank = built-in layout.'],
  ['QueueBuster template file ID', '', 'Set from the app. Blank = built-in layout.'],
  ['Invoice folder ID', '', 'Drive folder for uploaded invoices (created automatically).']
];

// ───────────────────────────── web app ─────────────────────────────
function doGet(e) {
  if (e && e.parameter && e.parameter.b) return billPage_(e.parameter.b);   // customer bill link (Billing.gs)
  if (e && e.parameter && e.parameter.ap) return apLinkPage_(e.parameter);  // discount approval link from the email
  let page = HtmlService.createHtmlOutputFromFile('Index').getContent();
  const at = page.lastIndexOf('</body>');
  page = page.slice(0, at) + HtmlService.createHtmlOutputFromFile('BillingUI').getContent() + '\n' + page.slice(at);
  return HtmlService.createHtmlOutput(page).setTitle(APP_NAME)
    .addMetaTag('viewport', 'width=device-width, initial-scale=1, maximum-scale=1, viewport-fit=cover')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/** JSON API for the installed app (vermakshat.com/nutvique), which runs outside Google's frame so the camera and Bluetooth work.
 *  POST body (text/plain) = JSON {pin|token, action, data} → {ok:true, r:result} or {ok:false, e:message}. */
function doPost(e) {
  let out;
  try { out = { ok: true, r: api(JSON.parse((e && e.postData && e.postData.contents) || '{}')) }; }
  catch (err) { out = { ok: false, e: String((err && err.message) || err).replace(/^(Error|Exception):\s*/, '') }; }
  return ContentService.createTextOutput(JSON.stringify(out)).setMimeType(ContentService.MimeType.JSON);
}

/** Single entry point for the page. req = {pin, action, data}. */
function api(req) {
  req = req || {};
  const action = String(req.action || '');
  if (action === 'hello') return hello_(req);
  if (action === 'loginNames') return loginNames_();
  if (action === 'upiSms') return upiSms_(req);                 // iPhone Shortcut forwards the ICICI credit SMS (secret key, no login)
  if (action === 'login') return login_(req.data || {});
  if (action === 'setOwnerPin') return setFirstOwnerPin_(req.data);
  if (action === 'logout') return logout_(req);
  const user = auth_(req);
  const need = ACTION_RIGHT[action];
  if (need && !can_(user, need)) throw new Error('You do not have the right for this ("' + RIGHT_LABEL[Array.isArray(need) ? need[0] : need] + '"). Ask the owner.');
  const d = req.data || {};
  if (PRODUCT_ACTIONS[action] || (action === 'createBill' && (d.lines || []).some(l => l && l.saveNew))) return trackProductChanges_(() => apiCase_(action, d, user));
  return apiCase_(action, d, user);
}
function apiCase_(action, d, user) {
  const role = can_(user, 'costs') ? 'owner' : 'staff';     // 'owner' view = cost prices visible
  switch (action) {
    case 'ver': return vers_();
    case 'me': return { user: pub_(user) };
    case 'changePin': return changePin_(d, user);
    case 'listUsers': return listUsers_(user);
    case 'saveUser': return saveUser_(d, user);
    case 'resetPin': return resetPin_(d, user);
    case 'requestApproval': return requestApproval_(d, user);
    case 'approvalStatus': return approvalStatus_(d, user);
    case 'approvalList': if (!can_(user, 'approve') && !canApproveAccess_(user)) throw new Error('You cannot approve requests.'); return approvalList_(user);
    case 'decideStoreAccess': return decideStoreAccess_(d, user);
    case 'requestStoreAccess': return requestStoreAccess_(d, user);
    case 'storeAccessStatus': return storeAccessStatus_(d, user);
    case 'decideApproval': return decideApproval_(d, user);
    case 'makeCodes': return makeCodes_(d, user);
    case 'listCodes': return listCodes_();
    case 'checkApprovalCode': return checkApprovalCode_(d, user);
    case 'boot': return boot_(user);
    case 'start': return { boot: boot_(user), bill: can_(user, 'bill') ? billBoot_(d, user) : null };   // one round trip when the app opens
    case 'stock': return { stock: filterStock_(stockMap_(true), stockScope_(user)), at: new Date().toISOString() };
    case 'productDetail': return productDetail_(d.sku, role, user);
    case 'stockBoot': return stockBoot_(user);
    case 'goodsIn': return goodsIn_(d, user);
    case 'sendTransfer': return sendTransfer_(d, user);
    case 'transfers': return transfersList_(d, user);
    case 'checkTransfer': return checkTransfer_(d, user);
    case 'stockOut': return stockOut_(d, user);
    case 'movements': return movements_(d, user);
    case 'customerInfo': return customerInfo_(d, user);
    case 'customersReport': return customersReport_(d, user);
    case 'customerList': return customerList_(d, user);
    case 'customerDetail': return customerDetail_(d, user);
    case 'readInvoice': return readInvoice_(d);
    case 'saveDraft': return saveDraft_(d);
    case 'deleteDraft': return deleteDraft_(d.id);
    case 'getInvoice': return getInvoice_(d.id);
    case 'listInvoices': return listInvoices_();
    case 'postInvoice': return postInvoiceX_(d);
    case 'reviseInvoice': return reviseInvoice_(d);
    case 'invoiceForEdit': return invoiceForEdit_(d.id);
    case 'purchaseBoot': return purchaseBoot_();
    case 'addDeliveryCharge': return addDeliveryCharge_(d, user);
    case 'removeDeliveryCharge': return removeDeliveryCharge_(d);
    case 'setCostOverride': return setCostOverride_(d, user);
    case 'clearCostOverride': return clearCostOverride_(d);
    case 'previewNew': return previewNew_(d);
    case 'createProduct': return createProductsApi_(d);
    case 'updateProduct': return updateProduct_(d);
    case 'gs1Queue': return gs1Queue_();
    case 'qbDone': clearQbPending_(d.skus); return gs1Queue_();
    case 'exportFile': return exportFile_(d);
    case 'markGs1': return markGs1_(d);
    case 'adjustStock': return adjustStock_(d, user);
    case 'storePrices': return storePriceList_();
    case 'setStorePrices': return setStorePrices_(d, user);
    case 'applyStorePrices': return applyStorePrices_(d, user);
    case 'clearStorePrices': return clearStorePrices_(d);
    case 'copyStorePrices': return copyStorePrices_(d, user);
    case 'countSheet': return countSheet_(d, user);
    case 'saveCount': return saveCount_(d, user);
    case 'countHistory': return countHistory_(d, user);
    case 'importMovements': return importMovements_(d, user);
    case 'getSettings': return getSettingsForUi_(user);
    case 'saveSettings': return saveSettings_(d, user);
    case 'saveTemplate': return saveTemplate_(d);
    case 'syncNc': return { products: syncProductsToNightClosing() };
  }
  const billed = billingApi_(action, d, user);   // Bill screen (Billing.gs)
  if (billed !== undefined) return billed;
  throw new Error('Unknown action: ' + action);
}

function hello_(req) {
  if (!String(setting_('Owner PIN', '') || '').trim()) return { needOwnerPin: true };
  try { return { user: pub_(auth_(req)) }; } catch (e) { return {}; }
}
function setFirstOwnerPin_(d) {
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    const s = settings_();
    if (String(s['Owner PIN'] || '').trim()) throw new Error('Owner PIN is already set.');
    const pin = String(d && d.pin || '').trim();
    if (!/^\d{4,8}$/.test(pin)) throw new Error('PIN must be 4 to 8 digits.');
    setSetting_('Owner PIN', pin);
    return { role: 'owner' };
  } finally { lock.releaseLock(); }
}

// ───────────────────────────── setup ─────────────────────────────
/** Run once from the editor (or it runs by itself on first open). Creates every tab and loads the product list. */
function setup() {
  const ss = book_();
  Object.keys(T).forEach(k => tab_(k));
  const ps = tab_('products');
  if (ps.getLastRow() < 2) {
    const now = new Date();
    const rows = SEED_PRODUCTS.map(p => {
      const r = new Array(H.products.length).fill('');
      r[PC.sku] = p.sku; r[PC.gtin] = p.gtin; r[PC.name] = p.name; r[PC.short] = p.short; r[PC.cat] = p.cat; r[PC.pack] = p.pack;
      r[PC.net] = p.net; r[PC.unit] = p.unit; r[PC.hsn] = p.hsn; r[PC.gst] = p.gst; r[PC.sell] = p.sell == null ? '' : p.sell;
      r[PC.mrp] = p.mrp == null ? '' : p.mrp; r[PC.gs1] = p.gs1; r[PC.status] = 'Active'; r[PC.created] = now; r[PC.updated] = now;
      return r;
    });
    ps.getRange(2, 1, rows.length, rows[0].length).setValues(rows);
  }
  const gs = tab_('gtins');
  if (gs.getLastRow() < 2) gs.getRange(2, 1, SEED_GTINS.length, 5).setValues(SEED_GTINS);
  const st = tab_('settings');
  const have = st.getLastRow() < 2 ? [] : st.getRange(2, 1, st.getLastRow() - 1, 1).getValues().map(r => String(r[0]));
  const add = DEFAULT_SETTINGS.filter(s => have.indexOf(s[0]) < 0);
  if (add.length) st.getRange(st.getLastRow() + 1, 1, add.length, 3).setValues(add);
  ['Sheet1'].forEach(n => { const s = ss.getSheetByName(n); if (s && ss.getSheets().length > 1 && s.getLastRow() === 0) ss.deleteSheet(s); });
  CacheService.getScriptCache().removeAll(['settings', 'stock']);
  return 'Setup done: ' + (ps.getLastRow() - 1) + ' products, ' + (gs.getLastRow() - 1) + ' GTINs.';
}

function book_() {
  const id = PropertiesService.getScriptProperties().getProperty('BOOK_ID');
  if (id) return SpreadsheetApp.openById(id);
  const ss = SpreadsheetApp.getActive();
  if (!ss) throw new Error('Open the script from its Google Sheet (Extensions → Apps Script) and run setup once.');
  PropertiesService.getScriptProperties().setProperty('BOOK_ID', ss.getId());
  return ss;
}
function tab_(key) {
  const ss = book_();
  let sh = ss.getSheetByName(T[key]);
  if (!sh) {
    sh = ss.insertSheet(T[key]);
    const h = H[key];
    sh.getRange(1, 1, 1, h.length).setValues([h]).setFontWeight('bold').setBackground('#1F2A44').setFontColor('#F7F1DE').setWrap(true);
    sh.setFrozenRows(1);
    const fmt = { products: () => { sh.getRange('A:B').setNumberFormat('@'); sh.getRange('J:J').setNumberFormat('@');
        sh.getRange('L:O').setNumberFormat('#,##0.00'); sh.setFrozenColumns(3); sh.setColumnWidth(3, 320); sh.setColumnWidth(4, 260); },
      gtins: () => sh.getRange('A:A').setNumberFormat('@'),
      invoices: () => { sh.getRange('A:A').setNumberFormat('@'); sh.getRange('E:F').setNumberFormat('@'); sh.hideColumns(22); },
      lines: () => { sh.getRange('A:A').setNumberFormat('@'); sh.getRange('D:D').setNumberFormat('@'); },
      ledger: () => { sh.getRange('A:A').setNumberFormat('@'); sh.setColumnWidth(4, 300); },
      aliases: () => { sh.setColumnWidth(2, 260); sh.setColumnWidth(5, 300); },
      settings: () => { sh.setColumnWidth(1, 240); sh.setColumnWidth(2, 300); sh.setColumnWidth(3, 520); sh.getRange('B:B').setNumberFormat('@'); }
    };
    if (fmt[key]) fmt[key]();
  }
  return sh;
}
function rows_(key) {
  const sh = tab_(key), n = sh.getLastRow() - 1;
  return n < 1 ? [] : sh.getRange(2, 1, n, H[key].length).getValues();
}
function append_(key, rows) {
  if (!rows.length) return;
  const sh = tab_(key);
  sh.getRange(sh.getLastRow() + 1, 1, rows.length, rows[0].length).setValues(rows);
}

// ───────────────────────────── settings ─────────────────────────────
function settings_() {
  const c = CacheService.getScriptCache(), hit = c.get('settings');
  if (hit) return JSON.parse(hit);
  const sh = book_().getSheetByName(T.settings);
  if (!sh) { setup(); return settings_(); }
  const o = {};
  if (sh.getLastRow() > 1) sh.getRange(2, 1, sh.getLastRow() - 1, 2).getValues().forEach(r => { if (r[0]) o[String(r[0])] = r[1]; });
  c.put('settings', JSON.stringify(o), 300);
  return o;
}
function setting_(k, dflt) { const v = settings_()[k]; return v === '' || v == null ? dflt : v; }
function num_(k, dflt) { const v = Number(setting_(k, dflt)); return isFinite(v) ? v : dflt; }
function setSetting_(k, v) {
  const sh = tab_('settings');
  const n = sh.getLastRow() - 1;
  const keys = n < 1 ? [] : sh.getRange(2, 1, n, 1).getValues().map(r => String(r[0]));
  const i = keys.indexOf(k);
  if (i >= 0) sh.getRange(i + 2, 2).setValue(v); else sh.appendRow([k, v, '']);
  CacheService.getScriptCache().remove('settings');
}
const EDITABLE_SETTINGS = ['Staff PIN', 'Owner PIN', 'Gemini model', 'Markup (selling = cost ×)', 'Round selling price up to', 'MRP = selling ×',
  'Minimum margin %', 'Cost includes GST', 'Spread charges by', 'Night Closing sheet ID', 'Last GTIN used on DataKart',
  "Lucky draw: bill of at least ₹", "Lucky draw: chance of 10% coupon (out of 100)", "Lucky draw: coupon valid (days)", "Lucky draw: coupon needs bill of ₹", "Referral: friend's bill at least ₹", "Referral: coupon %", "Referral: coupon needs bill of ₹", "Referral: coupon valid (months)", "Discount: round off without approval up to ₹", "UPI email check", "UPI email search", "UPI SMS account ends with", "Google Contacts: save customers", "Day close emails: also send to", "Card terminals (ID = store)"];
function getSettingsForUi_(user) {
  const s = settings_();
  const o = {}; EDITABLE_SETTINGS.forEach(k => o[k] = s[k] == null ? '' : String(s[k]));
  if (!user || user.role !== 'Owner') delete o['Owner PIN'];
  delete o['Staff PIN'];
  o.hasGeminiKey = !!PropertiesService.getScriptProperties().getProperty('GEMINI_KEY');
  o.gs1Template = !!s['GS1 template file ID']; o.qbTemplate = !!s['QueueBuster template file ID'];
  o.sheetUrl = book_().getUrl();
  return o;
}
function saveSettings_(d, user) {
  Object.keys(d || {}).forEach(k => {
    if ((k === 'Owner PIN' && (!user || user.role !== 'Owner')) || k === 'Staff PIN') return;
    if (k === 'geminiKey') { const v = String(d[k] || '').trim(); if (v) PropertiesService.getScriptProperties().setProperty('GEMINI_KEY', v); return; }
    if (EDITABLE_SETTINGS.indexOf(k) < 0) return;
    if (k === 'Owner PIN' && !/^\d{4,8}$/.test(String(d[k]).trim())) throw new Error('Owner PIN must be 4 to 8 digits.');
    if (k === 'Staff PIN' && String(d[k]).trim() && !/^\d{4,8}$/.test(String(d[k]).trim())) throw new Error('Staff PIN must be 4 to 8 digits (or blank).');
    setSetting_(k, String(d[k]).trim());
  });
  return getSettingsForUi_(user);
}

// ───────────────────────────── products ─────────────────────────────
function productRows_() { return rows_('products').filter(r => String(r[PC.sku]).trim()); }
function prodObj_(r, role) {
  const o = { sku: s_(r[PC.sku]), gtin: s_(r[PC.gtin]), name: s_(r[PC.name]), seller: s_(r[PC.seller]), short: s_(r[PC.short]),
    cat: s_(r[PC.cat]), pack: s_(r[PC.pack]), net: n_(r[PC.net]), unit: s_(r[PC.unit]) || 'kg', hsn: s_(r[PC.hsn]), gst: n_(r[PC.gst]),
    sell: n_(r[PC.sell]), mrp: n_(r[PC.mrp]), gs1: s_(r[PC.gs1]), status: s_(r[PC.status]) || 'Active', reorder: n_(r[PC.reorder]),
    supplier: s_(r[PC.supplier]), lastBuy: ymd_(r[PC.lastBuy]) };
  if (role === 'owner') { o.cost = n_(r[PC.cost]); o.avg = n_(r[PC.avg]); o.notes = s_(r[PC.notes]); }
  return o;
}
function boot_(user) {
  if (!book_().getSheetByName(T.products)) setup();
  const role = can_(user, 'costs') ? 'owner' : 'staff';
  const pk = 'pl_' + role + '_' + (PropertiesService.getScriptProperties().getProperty('PRODUCTS_VER') || '0');
  let products = cget_(pk);
  if (!products) { products = productRows_().map(r => prodObj_(r, role)); cput_(pk, products, 120); }
  const scope = stockScope_(user);
  const out = Object.assign({ role: user.role === 'Owner' ? 'owner' : 'staff', user: pub_(user), products: products,
    stock: can_(user, 'stockView') ? filterStock_(stockMap_(false), scope) : {},
    locations: scope ? locations_().filter(l => scope.indexOf(l) >= 0) : locations_(), at: new Date().toISOString(), storePrices: storePrices_() }, vers_());
  if (can_(user, ['prices', 'newProduct', 'invoices', 'gs1'])) {
    out.settings = { markup: num_('Markup (selling = cost ×)', 2), round: num_('Round selling price up to', 10), mrpX: num_('MRP = selling ×', 1.25),
      minMargin: num_('Minimum margin %', 30), costGst: String(setting_('Cost includes GST', 'No')) === 'Yes',
      spread: String(setting_('Spread charges by', 'Value')), hasKey: !!PropertiesService.getScriptProperties().getProperty('GEMINI_KEY'),
      nextGtin: nextGtins_(1)[0] || '' };
    out.categories = CATEGORIES.map(c => c[0]).concat(['Gift Hampers']);
  }
  if (can_(user, 'invoices')) out.drafts = listInvoices_().filter(x => x.status === 'Draft').length;
  if (can_(user, 'gs1')) out.gs1Pending = products.filter(p => needsGs1_(p.gs1)).length + Object.keys(qbPending_()).length;
  return out;
}
function locations_() {
  const set = LOCATIONS.slice(), st = stockMap_(false);
  Object.keys(st).forEach(k => Object.keys(st[k].q || {}).forEach(l => { if (set.indexOf(l) < 0) set.push(l); }));
  return set;
}
function findProductRow_(sku) {
  const sh = tab_('products'), n = sh.getLastRow() - 1;
  if (n < 1) return -1;
  const skus = sh.getRange(2, 1, n, 1).getValues().map(r => String(r[0]).trim());
  const i = skus.indexOf(String(sku).trim());
