/** GS1 status that still needs work (not registered, not another brand's product). */
function needsGs1_(st) { return !!st && st !== 'Registered' && st !== 'Other brand'; }
/** Products of other brands that we resell (honey, chips, bars…). They keep their own barcode and never get a Nutvique GTIN.
 *  list: [{name, barcode, unit:'pcs'|'kg', mrp, sell, cat, supplier}] → returns [{sku, name}] (existing barcode/name is reused). */
function addExternalProducts_(list) {
  const ps = productRows_();
