  const byBarcode = {}, byName = {};
  ps.forEach(r => { if (s_(r[PC.gtin])) byBarcode[s_(r[PC.gtin])] = s_(r[PC.sku]); byName[norm_(r[PC.name])] = s_(r[PC.sku]); });
  const now = new Date(), out = [], add = [];
