    const name = txt_(it.name, 120).replace(/\s+/g, ' ');
    if (!name) return;
    const bc = String(it.barcode || '').replace(/\D/g, '');
    const have = (bc && byBarcode[bc]) || byName[norm_(name)];
    if (have) { out.push({ sku: have, name: name, existing: true }); return; }
    let sku = 'EXT-' + (bc || norm_(name).replace(/ /g, '').slice(0, 14)), k = 2;
    while (taken.has(sku)) sku = sku.replace(/-\d+$/, '') + '-' + (k++);
    taken.add(sku); if (bc) byBarcode[bc] = sku; byName[norm_(name)] = sku;
    const r = new Array(H.products.length).fill('');
    r[PC.sku] = sku; r[PC.gtin] = bc; r[PC.name] = name; r[PC.cat] = txt_(it.cat, 80); r[PC.pack] = 'Packed'; r[PC.net] = 1;
    r[PC.unit] = it.unit === 'kg' ? 'kg' : 'pcs'; r[PC.gst] = n_(it.gst) || ''; r[PC.hsn] = String(it.hsn || '').replace(/\D/g, '').slice(0, 8); r[PC.sell] = n_(it.sell) || n_(it.mrp) || ''; r[PC.mrp] = n_(it.mrp) || '';
    r[PC.gs1] = 'Other brand'; r[PC.status] = 'Active'; r[PC.supplier] = txt_(it.supplier, 120); r[PC.notes] = txt_(it.note, 300);
