// ───────────────────────────── GTIN / SKU / HSN ─────────────────────────────
function checkDigit_(body12) {
  let sum = 0;
  for (let i = 0; i < 12; i++) sum += Number(body12[i]) * (i % 2 === 0 ? 1 : 3);
  return String((10 - (sum % 10)) % 10);
}
function gtinFromRef_(prefix, ref) { const b = prefix + String(ref).padStart(12 - prefix.length, '0'); return b + checkDigit_(b); }
function validGtin_(g) { g = String(g); return /^\d{13}$/.test(g) && checkDigit_(g.slice(0, 12)) === g[12]; }
/** Next n free GTINs: always after the highest GTIN ever issued (register, products, and the DataKart setting). */
function nextGtins_(n) {
  const prefix = String(setting_('GS1 company prefix', '890622285'));
  const refLen = 12 - prefix.length;
  let max = -1;
  const take = g => { g = String(g || '').trim(); if (g.indexOf(prefix) === 0 && g.length === 13) max = Math.max(max, Number(g.slice(prefix.length, 12))); };
  rows_('gtins').forEach(r => take(r[0]));
  productRows_().forEach(r => take(r[PC.gtin]));
  take(setting_('Last GTIN used on DataKart', ''));
  const out = [];
  for (let i = 1; i <= n; i++) {
    const ref = max + i;
    if (ref >= Math.pow(10, refLen)) throw new Error('Your GS1 range is full – buy more GTINs from GS1 India.');
    out.push(gtinFromRef_(prefix, ref));
  }
  return out;
}
function cleanWords_(name) {
  return String(name || '').toUpperCase().replace(/NUTVIQUE/g, ' ').replace(/\(LOOSE\)/g, ' ').replace(/\b\d+\s*(GM|G|GMS|KG|ML|PC|PCS)\b/g, ' ')
    .replace(/[^A-Z0-9 ]+/g, ' ').split(/\s+/).filter(w => w && ['AND', 'OF', 'THE', 'WITH'].indexOf(w) < 0);
}
function skuSize_(pack, net, unit) {
  if (pack !== 'Packed') return 'LSE';
  const u = String(unit || '').toLowerCase();
  if (/^g/.test(u)) return Math.round(net) + 'G';
  if (/^kg/.test(u)) return net + 'KG';
  return 'PC';
}
function autoSku_(name, cat, pack, net, unit, taken) {
  const c = CATEGORIES.find(x => x[0] === cat);
  const code = c ? c[1] : (cat === 'Gift Hampers' ? 'HMP' : 'GEN');
  const w = cleanWords_(name);
  let ini = w.slice(0, 3).map(x => x[0]).join('');
  if (ini.length < 3 && w[0]) ini = (ini + w[0].slice(1)).slice(0, 3);
  ini = ini || 'NEW';
  const size = skuSize_(pack, net, unit);
  let sku = 'NV-' + code + '-' + ini + '-' + size, k = 2;
  while (taken.has(sku)) sku = 'NV-' + code + '-' + ini + (k++) + '-' + size;
  return sku;
}
/** HSN + GST: supplier's HSN on the invoice first, then category default (if it decides), then keyword rules. */
function autoHsn_(name, cat, invoiceHsn, invoiceGst) {
  const ih = String(invoiceHsn || '').replace(/\D/g, '');
  const gstFromRule = () => { const r = ruleHsn_(name); return r ? r[2] : null; };
  if (ih.length >= 6) return { hsn: ih.slice(0, 6), gst: n_(invoiceGst) || gstFromRule() || 5, from: 'supplier invoice' };
  const c = CATEGORIES.find(x => x[0] === cat);
  if (c && c[4]) return { hsn: c[2], gst: c[3], from: 'category' };
  const r = ruleHsn_(name);
  if (r) return { hsn: r[1], gst: r[2], from: 'keyword "' + r[0] + '"' };
  if (c) return { hsn: c[2], gst: c[3], from: 'category' };
  return { hsn: '', gst: 5, from: '' };
}
function ruleHsn_(name) { const u = String(name || '').toUpperCase(); return HSN_RULES.find(r => u.indexOf(r[0]) >= 0) || null; }

/** Suggestion for a new product (used by the invoice screen and "New product"). */
function previewNew_(d) {
  const taken = new Set(productRows_().map(r => s_(r[PC.sku])));
  const out = (d.items || []).map(it => {
    const pack = it.pack === 'Packed' ? 'Packed' : 'Loose';
    const hs = autoHsn_(it.name + ' ' + (it.seller || ''), it.cat, it.hsn, it.gst);
    const sku = autoSku_(it.name, it.cat, pack, n_(it.net), it.netUnit || 'g', taken); taken.add(sku);
    return { sku: sku, hsn: hs.hsn, gst: hs.gst, hsnFrom: hs.from };
  });
