}

/** Creates products (issues GTINs). items: [{name, short, cat, pack, net, unit, hsn, gst, sell, mrp, cost, seller, supplier}] */
function createProducts_(items, source) {
  const ps = productRows_();
  const taken = new Set(ps.map(r => s_(r[PC.sku])));
  const names = new Set(ps.map(r => norm_(r[PC.name])));
  const gt = nextGtins_(items.length);
  const now = new Date(), created = [];
  items.forEach((it, i) => {
    const name = txt_(it.name, 120);
    if (!name) throw new Error('A new product has no name.');
    if (!/^nutvique\b/i.test(name)) throw new Error('"' + name + '": Nutvique names must start with "Nutvique".');
    if (names.has(norm_(name))) throw new Error('"' + name + '" already exists – pick it instead of creating it again.');
    const pack = it.pack === 'Packed' ? 'Packed' : 'Loose';
    const unit = pack === 'Loose' ? 'kg' : 'pcs';
    const net = pack === 'Loose' ? 1 : n_(it.net);
    if (pack === 'Packed' && !net) throw new Error('"' + name + '": enter the net content of one pack.');
    const sell = round2_(n_(it.sell)), mrp = round2_(n_(it.mrp)), cost = round2_(n_(it.cost));
    if (!sell || !mrp) throw new Error('"' + name + '": enter selling price and MRP.');
    if (sell > mrp) throw new Error('"' + name + '": selling price is higher than MRP.');
    const hs = autoHsn_(name + ' ' + (it.seller || ''), it.cat, it.hsn, it.gst);
    let sku = txt_(it.sku, 40).toUpperCase();
    if (!sku || taken.has(sku)) sku = autoSku_(name, it.cat, pack, net, it.netUnit || 'g', taken);
    taken.add(sku); names.add(norm_(name));
    const r = new Array(H.products.length).fill('');
    r[PC.sku] = sku; r[PC.gtin] = gt[i]; r[PC.name] = name; r[PC.seller] = it.seller ? (it.supplier ? it.supplier + ': ' : '') + it.seller : '';
    r[PC.short] = txt_(it.short, 40) || name.replace(/^nutvique\s+/i, '').slice(0, 40); r[PC.cat] = txt_(it.cat, 80);
    r[PC.pack] = pack; r[PC.net] = net; r[PC.unit] = unit; r[PC.hsn] = String(it.hsn || hs.hsn).replace(/\D/g, '').slice(0, 8) || hs.hsn;
    r[PC.gst] = n_(it.gst) || hs.gst; r[PC.cost] = cost || ''; r[PC.avg] = cost || ''; r[PC.sell] = sell; r[PC.mrp] = mrp;
    r[PC.margin] = margin_(cost, sell); r[PC.gs1] = 'To upload'; r[PC.status] = 'Active'; r[PC.supplier] = txt_(it.supplier, 120);
    r[PC.notes] = (pack === 'Packed' ? 'Pack: ' + net + ' ' + (it.netUnit || 'g') + '. ' : '') + (source || '');
    r[PC.created] = now; r[PC.updated] = now;
    append_('products', [r]);
    append_('gtins', [[gt[i], sku, name, ymd_(now), source || 'Created in Inventory app']]);
    append_('prices', [[now, sku, name, '', cost || '', '', sell, '', mrp, 'New product', 'Owner']]);
    created.push({ sku: sku, gtin: gt[i], name: name });
  });
  return created;
}
function createProductsApi_(d) {
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
