const INVOICE_PROMPT = `You read Indian GST purchase invoices for Nutzy Foods Pvt Ltd (brand Nutvique, dry fruits / nuts / snacks).
Return ONLY JSON with this shape (numbers as numbers, no ₹ or commas):
{"supplier":{"name":"","gstin":""},"buyer_gstin":"","invoice_no":"","invoice_date":"YYYY-MM-DD",
 "lines":[{"description":"exact item text as printed, without the HSN in brackets","hsn":"","qty":0,"unit":"KGS/PCS/BOX/…",
   "rate_excl_tax":0,"rate_incl_tax":0,"discount_pct":0,"amount":0,"gst_pct":0}],
 "taxable_value":0,"cgst":0,"sgst":0,"igst":0,
 "other_charges":[{"label":"e.g. PACKING & FORWARDING","amount":0}],"round_off":0,"total":0,"total_qty":0,
 "suggestions":[{"line":1,"sku":"existing SKU or null","confidence":0.0,"alternatives":["SKU",...],
   "new_name":"","short_description":"","category":""}]}
Rules:
- "amount" is the taxable line amount (before GST). rate_excl_tax is the per-unit rate before GST.
- round_off is negative when the invoice says "Less: Round Off".
- other_charges are non-item charges added to the bill (packing, freight, cartage, insurance). Do not include GST.
- suggestions: one per line (line numbers start at 1). Match the supplier's generic item name to the most likely product in
  the Nutvique catalogue below (same product, not just same nut). confidence 0–1. If several catalogue products could be meant
  (e.g. "ALMOND CHOCODIP" could be any chocolate almond), give the best one in sku with confidence <= 0.6 and the others in
  alternatives. If nothing in the catalogue is that product, sku = null and suggest a Nutvique brand name in new_name in the
  same style as the catalogue ("Nutvique" + an evocative premium descriptor + the product, Title Case, max ~45 characters),
  a short_description under 40 characters, and the best category from the category list.
CATEGORY LIST: {{CATS}}
CATALOGUE (SKU | Nutvique name | seller names | HSN):
{{CATALOGUE}}`;

function gemini_(parts, wantJson) {
  const key = PropertiesService.getScriptProperties().getProperty('GEMINI_KEY');
  if (!key) throw new Error('No Gemini API key yet. Owner: More → Settings → paste the key from aistudio.google.com/apikey.');
  const models = [String(setting_('Gemini model', 'gemini-2.5-flash')), 'gemini-2.5-flash', 'gemini-flash-latest']
    .filter((m, i, a) => m && a.indexOf(m) === i);
  let lastErr = '';
  for (const m of models) {
    const res = UrlFetchApp.fetch('https://generativelanguage.googleapis.com/v1beta/models/' + encodeURIComponent(m) + ':generateContent', {
      method: 'post', contentType: 'application/json', muteHttpExceptions: true, headers: { 'x-goog-api-key': key },
      payload: JSON.stringify({ contents: [{ role: 'user', parts: parts }],
        generationConfig: Object.assign({ temperature: 0 }, wantJson ? { responseMimeType: 'application/json' } : {}) })
    });
    const code = res.getResponseCode(), body = res.getContentText();
    if (code === 200) {
      const j = JSON.parse(body);
      const t = (((j.candidates || [])[0] || {}).content || {}).parts || [];
      const text = t.map(p => p.text || '').join('');
      if (!wantJson) return text;
      const clean = text.replace(/^```(json)?/i, '').replace(/```\s*$/, '').trim();
      return JSON.parse(clean);
    }
    lastErr = code + ' ' + body.slice(0, 300);
    if (code !== 404 && code !== 400) break;      // only try another model if this one is unknown
  }
  throw new Error('Gemini could not read it: ' + lastErr);
}
function testGemini() { Logger.log(gemini_([{ text: 'Reply with the word OK' }], false)); }

/** d = {fileName, mime, base64}. Saves the file to Drive, asks Gemini, and returns a draft ready for review. */
function readInvoice_(d) {
  if (!d || !d.base64) throw new Error('No file.');
  const mime = String(d.mime || 'application/pdf');
  if (!/^(application\/pdf|image\/)/.test(mime)) throw new Error('Upload a PDF or a photo of the invoice.');
  const blob = Utilities.newBlob(Utilities.base64Decode(d.base64), mime, txt_(d.fileName, 120) || 'invoice');
  const file = invoiceFolder_().createFile(blob);
  const prods = productRows_().filter(r => s_(r[PC.status]) !== 'Discontinued');
  const catalogue = prods.map(r => [s_(r[PC.sku]), s_(r[PC.name]), s_(r[PC.seller]), s_(r[PC.hsn])].join(' | ')).join('\n');
  const prompt = INVOICE_PROMPT.replace('{{CATS}}', CATEGORIES.map(c => c[0]).join('; ')).replace('{{CATALOGUE}}', catalogue);
  const ai = gemini_([{ inline_data: { mime_type: mime, data: d.base64 } }, { text: prompt }], true);
  const draft = draftFromAi_(ai);
  draft.file = { id: file.getId(), url: file.getUrl(), name: file.getName() };
  return saveDraft_(draft);
}

/** Turns Gemini's JSON into the draft the review screen edits, adding product matches. */
function draftFromAi_(ai) {
  ai = ai || {};
  const sup = ai.supplier || {};
  const charges = (ai.other_charges || []).filter(c => n_(c.amount)).map(c => ({ label: txt_(c.label, 60) || 'Other charges', amount: round2_(n_(c.amount)) }));
  const d = {
    supplier: txt_(sup.name, 120), gstin: txt_(sup.gstin, 20).toUpperCase(), invoiceNo: txt_(ai.invoice_no, 40),
    invoiceDate: /^\d{4}-\d{2}-\d{2}$/.test(ai.invoice_date || '') ? ai.invoice_date : ymd_(new Date()),
    taxable: round2_(n_(ai.taxable_value)), gst: round2_(n_(ai.igst) + n_(ai.cgst) + n_(ai.sgst)), charges: charges,
    roundOff: round2_(n_(ai.round_off)), total: round2_(n_(ai.total)), receivedAt: CENTRAL, notes: '', buyerGstin: txt_(ai.buyer_gstin, 20)
  };
  const sugg = {}; (ai.suggestions || []).forEach(s => { sugg[Number(s.line)] = s; });
  d.lines = (ai.lines || []).map((l, i) => {
    const qty = n_(l.qty), amount = round2_(n_(l.amount) || qty * n_(l.rate_excl_tax));
    return { no: i + 1, desc: txt_(l.description, 160), hsn: String(l.hsn || '').replace(/\D/g, ''), qty: qty, unit: txt_(l.unit, 12).toUpperCase() || 'KGS',
      rate: round2_(n_(l.rate_excl_tax) || (qty ? amount / qty : 0)), amount: amount, gstPct: n_(l.gst_pct), ai: sugg[i + 1] || null };
  });
  matchLines_(d);
  return d;
}

/** Fills each line's allocations: remembered seller names first, then Gemini's pick, then fuzzy name match. */
function matchLines_(d) {
  const prods = productRows_().map(r => prodObj_(r, 'owner')).filter(p => p.status !== 'Discontinued');
  const bySku = {}; prods.forEach(p => bySku[p.sku] = p);
  const aliases = rows_('aliases');
  const supKey = norm_(d.supplier);
  d.lines.forEach(l => {
    const key = norm_(l.desc);
    const remembered = aliases.filter(a => norm_(a[2]) === key && (norm_(a[0]) === supKey || !supKey) && bySku[s_(a[3])]);
    const cands = fuzzy_(l.desc, prods).slice(0, 6).map(x => x.sku);
    if (l.ai) {
      (l.ai.alternatives || []).concat([l.ai.sku]).forEach(s => { if (s && bySku[s] && cands.indexOf(s) < 0) cands.unshift(s); });
    }
    l.candidates = cands.slice(0, 8);
    if (remembered.length) {
      const tot = remembered.reduce((a, r) => a + (n_(r[5]) || 1), 0);
      l.alloc = remembered.map(r => ({ sku: s_(r[3]), qty: round3_(l.qty * (n_(r[5]) || 1) / tot) }));
      l.how = 'remembered';
    } else if (l.ai && l.ai.sku && bySku[l.ai.sku]) {
      l.alloc = [{ sku: l.ai.sku, qty: l.qty }];
      l.how = n_(l.ai.confidence) >= 0.75 ? 'suggested' : 'check';
    } else {
      const f = fuzzy_(l.desc, prods)[0];
      if (f && f.score >= 0.75 && !(l.ai && l.ai.sku === null)) { l.alloc = [{ sku: f.sku, qty: l.qty }]; l.how = 'check'; }
      else {
