    ['MUESLI', 'MUESLI'], ['MILLET', 'MILLET RANGE'], ['EDAMAME', 'PROTEIN BEANS (EDAMAME)'], ['BEAN', 'PROTEIN (BROAD BEANS)'],
    ['PECAN', 'FLAVOURED PECANS'], ['MAKHANA', 'MAKHANA'], ['VEGETABLE', 'VACUUM DRIED VEGETABLES'], ['CHIPS', 'VACUUM DRIED VEGETABLES'],
