// Fuzzy matching between a supplier's item text and Nutvique names / remembered seller names.
const SYN = { PANCHRATAN: 'PANCHRATNA', PANCHRATNA: 'PANCHRATNA', BADAM: 'ALMOND', BADAAM: 'ALMOND', ALMONDS: 'ALMOND', KAJU: 'CASHEW',
  CASHEWS: 'CASHEW', PISTA: 'PISTACHIO', PISTACHIOS: 'PISTACHIO', AKHROT: 'WALNUT', WALNUTS: 'WALNUT', KISHMISH: 'RAISIN', KISMISH: 'RAISIN',
  RAISINS: 'RAISIN', MUSELI: 'MUESLI', CHOCODIP: 'CHOCO', CHOCOLATE: 'CHOCO', COCOA: 'CHOCO', DATES: 'DATE', LEAVES: 'LEAF',
  APRICOTS: 'APRICOT', BERRIES: 'BERRY', BLUEBERRIES: 'BLUEBERRY', CRANBERRIES: 'CRANBERRY', VEGETABLES: 'VEGETABLE', SEEDS: 'SEED',
  MIXTURE: 'MIX', MIXTURES: 'MIX', FLAVOURS: 'FLAVOUR', FLAVORS: 'FLAVOUR', FLAVORED: 'FLAVOUR', FLAVOURED: 'FLAVOUR', HEALTHY: 'WELLNESS',
  FOXNUT: 'MAKHANA', PLUMS: 'PLUM', FIGS: 'ANJEER', FIG: 'ANJEER', BEANS: 'BEAN', NUTS: 'NUT', CHIP: 'CHIPS' };
