function toks_(s) {
  return String(s || '').toUpperCase().replace(/\(.*?\)/g, ' ').replace(/[^A-Z0-9 ]+/g, ' ').split(/\s+/)
    .filter(w => w && !STOP[w] && !/^\d+$/.test(w)).map(w => SYN[w] || w);
}
function fuzzy_(desc, prods) {
  const a = toks_(desc);
  if (!a.length) return [];
  return prods.map(p => {
    const b = toks_(p.name + ' ' + (p.seller || ''));
    let hit = 0;
    a.forEach(w => { if (b.some(x => x === w || (w.length > 4 && x.indexOf(w) === 0) || (x.length > 4 && w.indexOf(x) === 0))) hit++; });
    let score = hit / a.length;
    if (p.seller && toks_(p.seller).join(' ').indexOf(a.join(' ')) >= 0) score += 0.5;
    if (p.unit === 'kg') score += 0.05;              // loose items are what suppliers bill by the kg
    return { sku: p.sku, score: score };
  }).filter(x => x.score > 0.34).sort((x, y) => y.score - x.score);
}

