  const byQty = String(setting_('Spread charges by', 'Value')) === 'Quantity';
  const withGst = String(setting_('Cost includes GST', 'No')) === 'Yes';
  const base = lines.reduce((a, l) => a + (byQty ? n_(l.qty) : n_(l.amount)), 0) || 1;
  return lines.map(l => {
    const share = charges * (byQty ? n_(l.qty) : n_(l.amount)) / base;
    const gst = withGst ? n_(l.amount) * (n_(l.gstPct) || 0) / 100 : 0;
    return { share: share, total: n_(l.amount) + share + gst };
