  if (!/^\d{4}-\d{2}-\d{2}$/.test(d.invoiceDate || '')) throw new Error('Enter the invoice date.');
  if (d.id && rows_('invoices').some(r => s_(r[0]) === d.id && s_(r[1]) === 'Posted')) throw new Error('This invoice is already posted.');
  const dupWarn = invoiceChecks_(d).find(w => w.indexOf('DUPLICATE') === 0);
  if (dupWarn) throw new Error(dupWarn);
  const addStock = d.addStock !== false;
  const now = new Date();
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  let id, created = [], ledgerRows = [], summary = { lines: 0, qty: 0, value: 0, priceChanges: 0 };
  try {
