        const qty = n_(l.create.qtyBooked) || n_(l.qty);
        return Object.assign({}, l.create, { seller: l.desc, supplier: d.supplier, hsn: l.create.hsn || l.hsn, gst: l.create.gst || l.gstPct,
          cost: qty ? lc[d.lines.indexOf(l)].total / qty : 0 });
      }), 'From invoice ' + d.invoiceNo + ' (' + d.supplier + ')');
      toCreate.forEach((l, i) => { l.alloc = [{ sku: made[i].sku, qty: n_(l.create.qtyBooked) || n_(l.qty), sell: n_(l.create.sell), mrp: n_(l.create.mrp) }]; });
      created = made;
    }
    // 2) validate allocations
    const psh = tab_('products');
    const prows = psh.getRange(2, 1, psh.getLastRow() - 1, H.products.length).getValues();
    const idx = {}; prows.forEach((r, i) => idx[s_(r[PC.sku])] = i);
    const lc = landed_(d);
    const lineRows = [];
    const aliasUpd = [];
    const prevQty = {}; rows_('lines').forEach(x => { const k = s_(x[11]); prevQty[k] = (prevQty[k] || 0) + n_(x[13]); });
    const priceRows = [];
    d.lines.forEach((l, li) => {
      if (l.skip) return;
