        const oldCost = n_(r[PC.cost]), oldSell = n_(r[PC.sell]), oldMrp = n_(r[PC.mrp]);
        const newSell = a.sell != null && a.sell !== '' ? round2_(n_(a.sell)) : oldSell;
        const newMrp = a.mrp != null && a.mrp !== '' ? round2_(n_(a.mrp)) : oldMrp;
        if (newMrp && newSell > newMrp) throw new Error(r[PC.name] + ': selling price is higher than MRP.');
        // average cost across all purchases of this product
