          newSell || '', newMrp || '', margin_(unitCost, newSell), created.some(c => c.sku === a.sku) ? 'Yes' : '']);
        if (addStock) ledgerRows.push([d.invoiceDate, d.receivedAt || CENTRAL, 'Goods in (invoice)', r[PC.name], a.sku, s_(r[PC.unit]),
          n_(a.qty), round2_(unitCost), round2_(value), 'INV-GRN-' + id.slice(5), txt_(d.supplier, 120), 'Invoice ' + d.invoiceNo + ' · ' + l.desc, 'Owner', now]);
        aliasUpd.push({ sup: d.supplier, desc: l.desc, sku: a.sku, name: r[PC.name], share: part, rate: n_(l.rate), landed: unitCost });
