      n_(d.roundOff), n_(d.total), tot.qty, d.lines.length, created.map(c => c.name).join(', '), addStock ? 'Yes' : 'No (already in Night Closing)',
      d.file ? d.file.url : '', d.notes || '', 'Owner', now, now, draftJson.length < 49000 ? draftJson : ''];
