/** Pushes every active product (name, unit, selling price, SKU, barcode) to the Night Closing Products tab. Keeps its other rows. */
function syncProductsToNightClosing() {
  const sh = ncBook_().getSheetByName('Products');
  if (!sh) throw new Error('Night Closing sheet has no Products tab.');
  const n = Math.max(sh.getLastRow() - 1, 0);
  const cur = n ? sh.getRange(2, 1, n, 6).getValues() : [];
  const bySku = {}; cur.forEach((r, i) => { const k = s_(r[3]); if (k) bySku[k] = i; });
  let lastUsed = 0; cur.forEach((r, i) => { if (s_(r[0])) lastUsed = i + 1; });
  const add = []; let changed = 0;
  productRows_().forEach(r => {
    if (s_(r[PC.status]) === 'Discontinued') return;
    const sku = s_(r[PC.sku]);
    const type = /^NV-HMP-/.test(sku) ? 'Gift hamper (per piece)' : (s_(r[PC.unit]) === 'kg' ? 'Loose (per kg)' : 'Packed (per piece)');
    const row = [s_(r[PC.name]), s_(r[PC.unit]) || 'kg', n_(r[PC.sell]) || '', sku, s_(r[PC.gtin]), type];
    if (sku in bySku) {
      const old = cur[bySku[sku]];
      if (row.some((v, k) => String(v) !== String(old[k]))) { cur[bySku[sku]] = row; changed++; }
    } else add.push(row);
