  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const sh = xtab_(TR_TAB, TR_H), rows = xrows_(TR_TAB, TR_H), idx = [];
    rows.forEach((r, i) => { if (s_(r[0]) === s_(d.no)) idx.push(i); });
    if (!idx.length) throw new Error('Transfer not found.');
    const first = rows[idx[0]];
    if (s_(first[10]) !== 'Waiting for check') throw new Error('This transfer was already ' + s_(first[10]).toLowerCase() + '.');
    if (!inScope_(stockScope_(user), s_(first[3]))) throw new Error('Only the receiving store (' + s_(first[3]) + ') can check this transfer.');
    if (s_(first[11]) === user.name && user.role !== 'Owner') throw new Error('The person who sent a transfer cannot check it – ask someone else.');
    const now = new Date(), date = ymd_(now), prods = prodMap_(), ledger = [], ref = 'INV-' + s_(d.no);
    idx.forEach(i => {
      const r = rows[i], sku = s_(r[5]), sent = n_(r[7]);
      const got = d.approve ? Math.max(0, round3_(d.received && d.received[sku] != null && d.received[sku] !== '' ? n_(d.received[sku]) : sent)) : '';
      const diff = d.approve ? round3_(got - sent) : '';
      sh.getRange(i + 2, 9, 1, 8).setValues([[got, diff, d.approve ? 'Approved' : 'Rejected', s_(r[11]), user.name, now, [s_(r[14]), txt_(d.remarks, 200)].filter(Boolean).join(' · '), r[15]]]);
      const p = prods[sku];
      if (d.approve && p) {
        ledger.push(ledgerRow_(date, s_(r[2]), 'Transfer out', p, -sent, ref, 'To ' + s_(r[3]), 'Sent by ' + s_(r[11]), user.name, now));
        if (got) ledger.push(ledgerRow_(date, s_(r[3]), 'Transfer in', p, got, ref, 'From ' + s_(r[2]), diff ? 'Received ' + got + ' of ' + sent + ' (difference ' + diff + ')' : 'Received in full', user.name, now));
      }
    });
    if (ledger.length) postLedger_(ledger, 'Transfer ' + d.no);
    PropertiesService.getScriptProperties().setProperty('STOCK_VER', String(Date.now()));
  } finally { lock.releaseLock(); }
  return { transfers: transfersList_({}, user), stock: filterStock_(stockMap_(true), stockScope_(user)) };
}
/** Stock out: damage, expiry, samples … d = {date, location, reason, lines:[{sku, qty}], note} */
function stockOut_(d, user) {
  if (!inScope_(stockScope_(user), d.location) || LOCATIONS.indexOf(d.location) < 0) throw new Error('Pick one of your locations.');
  const reason = OUT_REASONS.indexOf(d.reason) >= 0 ? d.reason : 'Other';
  if (reason === 'Other' && !txt_(d.note, 200)) throw new Error('Type what happened in the note.');
  const prods = prodMap_(), now = new Date(), date = okDate_(d.date), ref = 'INV-OUT-' + stamp_();
  const rows = (d.lines || []).filter(l => n_(l.qty) > 0).map(l => {
    const r = prods[l.sku]; if (!r) throw new Error('Unknown product ' + l.sku);
    return ledgerRow_(date, d.location, 'Stock out – ' + reason, r, -Math.abs(n_(l.qty)), ref, '', txt_(d.note, 200), user.name, now);
  });
  if (!rows.length) throw new Error('Add at least one product with a quantity.');
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try { postLedger_(rows, 'Stock out ' + ref); } finally { lock.releaseLock(); }
  return { ok: true, rows: rows.length, stock: filterStock_(stockMap_(true), stockScope_(user)) };
}
/** Movement history. d = {from, to, loc, kind, q} */
function movements_(d, user) {
  const scope = stockScope_(user);
  const to = /^\d{4}-\d{2}-\d{2}$/.test(d.to || '') ? d.to : ymd_(new Date());
  const from = /^\d{4}-\d{2}-\d{2}$/.test(d.from || '') ? d.from : ymd_(new Date(Date.now() - 7 * 864e5));
  const kind = d.kind || 'All', q = norm_(d.q || '');
  const kindOf = mv => /^Sale/i.test(mv) ? 'Sales' : /Goods in|Purchase|Invoice/i.test(mv) ? 'Stock in' : /Transfer/i.test(mv) ? 'Transfers' : /^Stock out|Damage|write-off/i.test(mv) ? 'Stock out'
    : /Event|returned|issued/i.test(mv) ? 'Events' : /count|Opening|adjust/i.test(mv) ? 'Counts / adjustments' : 'Other';
  const list = allMoves_().filter(m => m.date >= from && m.date <= to && inScope_(scope, m.loc) && (!d.loc || d.loc === 'All' || m.loc === d.loc))
    .map(m => Object.assign(m, { kind: kindOf(m.mv) })).filter(m => (kind === 'All' || m.kind === kind) && (!q || norm_(m.item + ' ' + m.sku + ' ' + m.ref + ' ' + m.party).indexOf(q) >= 0))
    .sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : (a.saved < b.saved ? 1 : -1)));
  const sum = {}; list.forEach(m => { const s = sum[m.kind] = sum[m.kind] || { n: 0 }; s.n++; });
  return { from: from, to: to, sum: sum, kinds: ['All', 'Stock in', 'Transfers', 'Sales', 'Stock out', 'Events', 'Counts / adjustments', 'Other'],
    list: list.slice(0, 600).map(m => { const o = { date: m.date, loc: m.loc, mv: m.mv, kind: m.kind, item: m.item, sku: m.sku, unit: m.unit, qty: m.qty, ref: m.ref, party: m.party, note: m.note, src: m.src };
      if (can_(user, 'costs')) o.value = m.value; return o; }), more: list.length > 600 };
}

