// ───────────────────────────── cache for big values (CacheService keeps max 100 KB per key) ─────────────────────────────
function cput_(k, obj, ttl) {
  try {
    const c = CacheService.getScriptCache(), str = JSON.stringify(obj), n = Math.ceil(str.length / 90000) || 1, o = {};
    for (let i = 0; i < n; i++) o[k + '#' + i] = str.slice(i * 90000, (i + 1) * 90000);
    c.putAll(o, ttl); c.put(k, String(n), ttl);
  } catch (e) { console.warn('cache put ' + k + ': ' + e); }
}
function cget_(k) {
  try {
    const c = CacheService.getScriptCache(), n = Number(c.get(k) || 0); if (!n) return null;
    const keys = []; for (let i = 0; i < n; i++) keys.push(k + '#' + i);
    const v = c.getAll(keys); let str = '';
    for (let i = 0; i < n; i++) { if (v[keys[i]] == null) return null; str += v[keys[i]]; }
    return JSON.parse(str);
  } catch (e) { return null; }
}
function cdel_(k) { try { CacheService.getScriptCache().remove(k); } catch (e) { } }

