  safe_('Products → Night Closing', syncProductsToNightClosing);
  const sh = xtab_(SP_TAB, SP_H), all = xrows_(SP_TAB, SP_H);
  all.forEach((r, i) => { if (s_(r[2]) === loc && s_(r[10]) === 'Active') sh.getRange(i + 2, 11).setValue('Applied to all stores ' + ymd_(new Date())); });
  spChanged_();
  return { applied: skus.length, list: storePriceList_() };
}
function clearStorePrices_(d) {
  const loc = s_(d && d.location), sku = s_(d && d.sku);
  const sh = xtab_(SP_TAB, SP_H), all = xrows_(SP_TAB, SP_H); let n = 0;
  all.forEach((r, i) => { if (s_(r[2]) === loc && (!sku || s_(r[0]) === sku) && s_(r[10]) === 'Active') { sh.getRange(i + 2, 11).setValue('Removed'); n++; } });
  spChanged_();
  return { removed: n, list: storePriceList_() };
}

/** Copy one store's store-only prices to another location (e.g. Gulshan → Event stalls). */
function copyStorePrices_(d, user) {
  const from = s_(d && d.from), to = s_(d && d.to), sp = (cdel_('sprices'), storePrices_())[from] || {};
  const items = Object.keys(sp).map(sku => ({ sku: sku, sell: sp[sku].sell, mrp: sp[sku].mrp }));
  if (!items.length) throw new Error('No store prices at ' + from + '.');
  return setStorePrices_({ location: to, source: 'Copied from ' + from, items: items }, user);
}

// ───────────────────────────── discount approval by email (v18.8, 23 Oct 2026) ─────────────────────────────
// Every person with the "approve" right (and the owner) gets an email with Approve / Reject buttons; the in-app banner still works.
function apSecret_() {
  const p = PropertiesService.getScriptProperties(); let k = p.getProperty('AP_SECRET');
  if (!k) { k = Utilities.getUuid() + Utilities.getUuid(); p.setProperty('AP_SECRET', k); }
  return k;
}
function apKey_(id, name) {
  return Utilities.computeHmacSha256Signature(id + '|' + name, apSecret_()).map(b => ((b + 256) % 256).toString(16).padStart(2, '0')).join('').slice(0, 24);
}
function apApprovers_(except) {
  const out = [], owner = String(setting_('Owner email', 'nutzyfoods@gmail.com') || '').trim();
  if (owner) out.push({ name: OWNER_NAME, email: owner });
  userRows_().forEach(x => {
    const u = userObj_(x.r), em = s_(x.r[UC['Email']]);
    if (u.active && em && u.name !== except && (u.role === 'Owner' || u.rights.indexOf('approve') >= 0)) out.push({ name: u.name, email: em });
  });
  return out;
}
function apEmail_(id, user, d, gross, disc, pct) {
  const url = ScriptApp.getService().getUrl(), list = apApprovers_(user.name);
  const where = txt_(d.loc, 60) + (d.event ? ' · ' + txt_(d.event, 100) : '');
  list.forEach(a => {
    const link = (yes) => url + '?ap=' + encodeURIComponent(id) + '&n=' + encodeURIComponent(a.name) + '&k=' + apKey_(id, a.name) + (yes == null ? '' : '&go=' + (yes ? 'yes' : 'no'));
    const html = '<div style="font-family:Arial,sans-serif;max-width:480px">' +
      '<h2 style="color:#1F2A44;margin:0 0 8px">Discount approval needed</h2>' +
      '<p style="font-size:16px;margin:0 0 6px"><b>' + user.name + '</b> asks for <b>' + pct + '%</b> (₹' + disc + ' off ₹' + gross + ')</p>' +
      '<p style="color:#555;margin:0 0 6px">' + where + '</p>' + (d.items ? '<p style="color:#555;font-size:13px;margin:0 0 14px">' + txt_(d.items, 400) + '</p>' : '') +
      '<a href="' + link(null) + '" style="display:inline-block;background:#C9A24A;color:#1F2A44;padding:12px 22px;border-radius:8px;font-weight:bold;text-decoration:none">Review &amp; approve</a>' +
      '<p style="color:#888;font-size:12px;margin-top:16px">Request ' + id + '. You can also approve in the Nutvique app (More → Discount approvals).</p></div>';
    MailApp.sendEmail({ to: a.email, subject: 'Discount ' + pct + '% – ' + user.name + ' – ' + where, htmlBody: html, name: 'Nutvique app' });
  });
  return list.length + ' email(s)';
}
function apLinkPage_(q) {
  const esc = v => String(v == null ? '' : v).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const page = (title, body) => HtmlService.createHtmlOutput('<meta name="viewport" content="width=device-width,initial-scale=1"><div style="font-family:Arial,sans-serif;max-width:460px;margin:24px auto;padding:0 16px">' +
    '<div style="background:#1F2A44;color:#F7F1DE;padding:12px 16px;border-radius:10px 10px 0 0;font-weight:bold;letter-spacing:.1em">NUTVIQUE</div><div style="border:1px solid #ddd;border-top:0;border-radius:0 0 10px 10px;padding:16px">' +
    '<h2 style="margin:0 0 10px;color:#1F2A44">' + esc(title) + '</h2>' + body + '</div></div>').setTitle('Nutvique – discount approval');
  const id = s_(q.ap), name = s_(q.n);
  if (!id || !name || s_(q.k) !== apKey_(id, name)) return page('Link not valid', '<p>This approval link is not valid.</p>');
  if (/^SA/.test(id)) return saLinkPage_(q, page);
  const rows = xrows_(AP_TAB, AP_H), r = rows.find(x => s_(x[0]) === id);
  if (!r) return page('Not found', '<p>Request ' + esc(id) + ' was not found.</p>');
  let approver;
  if (name === OWNER_NAME) approver = { name: OWNER_NAME, role: 'Owner', rights: [] };
  else { const f = userRows_().find(x => norm_(x.r[UC['Name']]) === norm_(name)); approver = f ? userObj_(f.r) : null; }
  if (!approver || (approver.role !== 'Owner' && (!approver.active || approver.rights.indexOf('approve') < 0))) return page('Not allowed', '<p>' + esc(name) + ' can no longer approve discounts.</p>');
  const info = '<p style="font-size:16px"><b>' + esc(s_(r[2])) + '</b> · <b>' + n_(r[8]) + '%</b> (₹' + n_(r[7]) + ' off ₹' + n_(r[6]) + ')</p><p style="color:#555">' + esc(s_(r[3])) + (s_(r[4]) ? ' · ' + esc(s_(r[4])) : '') + '</p>' +
    (s_(r[5]) ? '<p style="color:#555;font-size:13px">' + esc(s_(r[5])) + '</p>' : '');
  const age = (Date.now() - (r[1] instanceof Date ? r[1].getTime() : 0)) / 60000;
  if (s_(r[9]) === 'Pending' && (q.go === 'yes' || q.go === 'no')) {
    if (age > 120) return page('Too late', info + '<p>This request is more than 2 hours old. Ask the associate to send a new one.</p>');
    try { decideApproval_({ id: id, approve: q.go === 'yes' }, approver); } catch (e) { return page('Could not save', '<p>' + esc(e.message) + '</p>'); }
    return page(q.go === 'yes' ? 'Approved ✓' : 'Rejected', info + '<p>' + (q.go === 'yes' ? 'The associate\'s screen unlocks and the bill can be saved now.' : 'The associate has been told to lower the discount.') + '</p>');
  }
  if (s_(r[9]) !== 'Pending') return page(s_(r[9]), info + '<p>Already ' + esc(s_(r[9]).toLowerCase()) + ' by ' + esc(s_(r[10])) + '.</p>');
  const base = ScriptApp.getService().getUrl() + '?ap=' + encodeURIComponent(id) + '&n=' + encodeURIComponent(name) + '&k=' + s_(q.k);
  return page('Approve this discount?', info + '<div style="display:flex;gap:10px;margin-top:16px"><a href="' + base + '&go=no" style="flex:1;text-align:center;padding:14px;border:1px solid #c0392b;color:#c0392b;border-radius:8px;text-decoration:none;font-weight:bold">Reject</a>' +
    '<a href="' + base + '&go=yes" style="flex:1;text-align:center;padding:14px;background:#C9A24A;color:#1F2A44;border-radius:8px;text-decoration:none;font-weight:bold">Approve ' + n_(r[8]) + '%</a></div>' +
    '<p style="color:#888;font-size:12px;margin-top:14px">Approving as ' + esc(name) + '.</p>');
}

/** Run once from the editor so Google asks the owner to allow sending emails (discount approvals). */
function authorizeEmail() { MailApp.getRemainingDailyQuota(); Logger.log('Email allowed. Quota left today: ' + MailApp.getRemainingDailyQuota()); }

