/**
 * NUTVIQUE BILLING  –  GST tax invoices for the 3 stores and event stalls (part of the Inventory app)
 * -----------------------------------------------------------------------------------------------
 *  • Bill screen (tab "Bill" in the app): pick items, qty in g/kg/pcs, discount, customer, payment → Save.
 *  • Every bill gets the next number of its own series for the financial year (GUL/26-27/00001 …),
 *    is stored in "Bills" + "Bill Lines", and (stores only) takes the stock out of that store
 *    (Stock Ledger row "Sale (bill)", mirrored to the Night Closing ledger).
 *  • Customer copy: a private link (?b=<token>) that opens the full tax invoice – sent by WhatsApp.
 *  • Seller details (GSTIN, CIN, FSSAI per store, addresses, phone, footer) live in the "Bill Setup" tab.
 *  • Bills are never deleted: the owner can cancel one (stock goes back, number stays used).
 */

const BT = { bills: 'Bills', lines: 'Bill Lines', setup: 'Bill Setup', events: 'Bill Events', staff: 'Bill Staff' };
const BH = {
  bills: ['Bill no.', 'Date', 'Time', 'Location', 'Series', 'Seq', 'FY', 'Status', 'Customer name', 'Phone', 'Customer GSTIN',
    'Customer address', 'Place of supply', 'Event / venue', 'Items', 'Total qty', 'Gross ₹', 'Discount ₹', 'Taxable ₹', 'CGST ₹',
    'SGST ₹', 'IGST ₹', 'Round off ₹', 'Total ₹', 'Cash ₹', 'UPI ₹', 'Card ₹', 'Other ₹', 'Payment', 'Billed by', 'WhatsApp sent',
    'Token', 'Client ID', 'Saved at', 'Cancelled at', 'Cancel reason', 'Stock moved', 'Bill data'],
  lines: ['Bill no.', 'Date', 'Location', 'Line', 'SKU', 'Item', 'HSN', 'Unit', 'Qty', 'Rate ₹ (incl. GST)', 'Gross ₹', 'Discount ₹',
    'Amount ₹', 'GST %', 'Taxable ₹', 'CGST ₹', 'SGST ₹', 'IGST ₹', 'Status'],
  setup: ['Setting', 'Value', 'Note'],
  events: ['Event name', 'Venue / address', 'Start date', 'End date', 'Status', 'Notes'],
  staff: ['Name', 'Active', 'Notes']
};
const BILL_STAFF_SEED = ['Veer Pratap', 'Vikas Awasthi', 'Vikas Kumar', 'Sudesh Kumar', 'Prem Kashyap', 'Vinesh Kumar', 'Faisal Khan', 'Sunny Kumar'];
const BC = {}; BH.bills.forEach((h, i) => BC[h] = i);
const BILL_EVENT = 'Event';
const BILL_LOCS = ['Gulshan One29 Mall', 'City Galleria – Gaur City-2', 'Central Market – Sector 120', BILL_EVENT];

const BILL_SETUP_DEFAULTS = [
  ['Brand name', 'NUTVIQUE', 'Printed big at the top of the bill.'],
  ['Legal name', 'NUTZY FOODS PRIVATE LIMITED', 'As on the GST certificate.'],
  ['GSTIN', '09AALCN8840K1ZR', ''],
  ['State', 'Uttar Pradesh', ''], ['State code', '09', ''],
  ['CIN', 'U47219UW2026PTC256062', 'Companies Act: CIN must be on every bill.'],
  ['Registered office', 'Unit No A-0917, 9th Floor, Tower-A, ATS Bouquet, Plot No A-2/2, Sector-132, Noida, Gautam Buddha Nagar, Uttar Pradesh 201304', ''],
  ['Phone', '9811166570', 'Company phone printed on bills (Companies Act). Change if you want a store / customer-care number.'],
  ['Email', 'nutzyfoods@gmail.com', ''],
  ['Website', 'www.nutvique.com', ''],
  ['Gulshan One29 Mall | Series', 'GUL', 'Bill no. = series/FY/number, e.g. GUL/26-27/00001 (max 16 characters).'],
  ['Gulshan One29 Mall | Address', 'Unit No FF-115, 1st Floor, Gulshan One-29 Mall, Plot No C3-E1, Sector 129, Noida, Uttar Pradesh 201304', ''],
  ['Gulshan One29 Mall | FSSAI', '12726055001273', ''],
  ['City Galleria – Gaur City-2 | Series', 'CGL', ''],
  ['City Galleria – Gaur City-2 | Address', 'Shop No GF-23 & GF-30, Ground Floor, City Galeria Gaur City-2, Plot No GH-03, Sector-16C, Greater Noida, Uttar Pradesh 201318', ''],
  ['City Galleria – Gaur City-2 | FSSAI', '12726055001274', ''],
  ['Central Market – Sector 120 | Series', 'CMK', ''],
  ['Central Market – Sector 120 | Address', 'Shop No AF-17, First Floor, Central Market, Sector-120, Noida, Uttar Pradesh 201301', ''],
  ['Central Market – Sector 120 | FSSAI', '12726055001275', ''],
  ['Event | Series', 'EVT', 'Event-stall bills. Stock for events is issued / returned in the Night Closing Events screen, so event bills do not move stock.'],
  ['Event | Address', '', 'Blank = the event name / venue typed on the bill is printed.'],
  ['Event | FSSAI', '12726999000677', 'Central licence (head office).'],
  ['Default GST %', 5, 'Used when a product has no GST % in Products.'],
  ['Footer note', 'Prices are inclusive of GST. Thank you for shopping with Nutvique!', 'Printed at the bottom of every bill.'],
  ['WhatsApp message', 'Thank you for shopping at {brand}, {store}! Your bill {no} dated {date} for ₹{total} is here: {link}', '{brand} {store} {no} {date} {total} {link} {name} are filled in.'],
  ['WhatsApp app', 'WhatsApp Business', 'WhatsApp Business = on Android phones the bill always opens in WhatsApp Business (company number). Type "Any" to allow normal WhatsApp.'],
  ['UPI ID', 'MSNUTZYFOODSPRIVATELIMITED.eazypay@icici', 'From the ICICI Eazypay QR. The Bill screen shows a QR with the exact bill amount for this UPI ID.'],
  ['UPI name', 'M/S.NUTZY FOODS PRIVATE LIMITED', 'Payee name shown in the customer\'s UPI app.'],
  ['UPI ref', 'EZYS9811166570', 'Reference (tr) from the bank QR – keep as it is.'],
  ['Bill without phone', 'Yes', 'Yes = staff can save a print-only bill when the customer does not give a number.'],
  ['Stock out on bill', 'Yes', 'Yes = store bills take the items out of that store\'s stock.']
];

// ───────────────────────────── API hook (called from api() in Code.gs) ─────────────────────────────
/** Returns undefined for actions that are not billing actions. */
function billingApi_(action, d, user) {
  const map = {
    billBoot: () => billBoot_(d, user),
    billLists: () => Object.assign(billLists_(), ownerLists_(user)),
    addBillEvent: () => bumpVer_('LISTS_VER', addBillEvent_(d, user)),
    recordShort: () => recordShort_(d, user, false),
    changePayment: () => changePayment_(d, user),
    upiCheck: () => upiCheck_(d, user),
    giveCoupons: () => giveCoupons_(d, user),
    saveContact: () => { if (user.role !== 'Owner') throw new Error('Only the owner saves customers to contacts.'); return { result: gcSave_(d.name, d.phone, user, d.where || 'typed in the app') }; },
    dayCloseGet: () => dayCloseGet_(d, user),
    dayCloseSave: () => dayCloseSave_(d, user),
    dayCloseList: () => dayCloseList_(d, user),
    dayCloseCheck: () => dayCloseCheck_(d, user),
    cashPickupAdd: () => cashPickupAdd_(d, user),
    cashPickupList: () => cashPickupList_(d, user),
    cashPickupDecide: () => cashPickupDecide_(d, user),
    bankTally: () => bankTally_(d, user),
    bankTallyCheck: () => bankTallyCheck_(d, user),
    upiList: () => upiList_(d, user),
    upiMatch: () => upiMatch_(d, user),
    clearShort: () => clearShort_(d, user),
    saveBillLists: () => bumpVer_('LISTS_VER', saveBillLists_(d)),
    salesReport: () => salesReport_(d, user),
    luckyDraw: () => luckyDraw_(d, user),
    createBill: () => createBill_(d, user),
    listBills: () => listBills_(d, user),
    getBill: () => ({ bill: withLucky_(billInScope_(getBillByNo_(d.no), user)) }),
    markBillSent: () => { billInScope_(getBillByNo_(d.no), user); return markBillSent_(d.no); },
    cancelBill: () => { billInScope_(getBillByNo_(d.no), user); return cancelBill_(d, user); },
    saveBillSetup: () => saveBillSetup_(d),
    posImport: () => posImport_(d, user),
    waSendBill: () => waSendBill_(d, user),
    waSendCoupon: () => waSendCoupon_(d, user),
    waSettings: () => { waOwner_(user); return waPublic_(); },
    waSave: () => waSave_(d, user),
    waCheck: () => waCheck_(user),
    waMakeTemplates: () => waMakeTemplates_(user),
    waTest: () => waTest_(d, user)
  };
  if (!map[action]) return undefined;
  return map[action]();
}

// ───────────────────────────── tabs / setup ─────────────────────────────
function btab_(key) {
  const ss = book_();
  let sh = ss.getSheetByName(BT[key]);
  if (!sh) {
    sh = ss.insertSheet(BT[key]);
    const h = BH[key];
    sh.getRange(1, 1, 1, h.length).setValues([h]).setFontWeight('bold').setBackground('#1F2A44').setFontColor('#F7F1DE').setWrap(true);
    sh.setFrozenRows(1);
    if (key === 'bills') {
      sh.getRange('A:A').setNumberFormat('@'); sh.getRange('B:C').setNumberFormat('@'); sh.getRange('J:K').setNumberFormat('@');
      sh.getRange('AF:AG').setNumberFormat('@'); sh.getRange('Q:AB').setNumberFormat('#,##0.00'); sh.hideColumns(BC['Bill data'] + 1);
      sh.setFrozenColumns(1);
    }
    if (key === 'lines') { sh.getRange('A:B').setNumberFormat('@'); sh.getRange('G:G').setNumberFormat('@'); sh.setColumnWidth(6, 300); }
    if (key === 'events') {
      sh.getRange('A:D').setNumberFormat('@'); sh.setColumnWidth(1, 260); sh.setColumnWidth(2, 380);
      sh.getRange('E2:E1000').setDataValidation(SpreadsheetApp.newDataValidation().requireValueInList(['Open', 'Closed'], true).build());
      sh.getRange(1, 1).setNote('Only events with Status = Open show in the Bill screen. Add / close events here or in the app (Bill setup).');
    }
    if (key === 'staff') {
      sh.setColumnWidth(1, 220);
      sh.getRange('B2:B1000').setDataValidation(SpreadsheetApp.newDataValidation().requireValueInList(['Yes', 'No'], true).build());
      sh.getRange(2, 1, BILL_STAFF_SEED.length, 3).setValues(BILL_STAFF_SEED.map(n => [n, 'Yes', '']));
      sh.getRange(1, 1).setNote('Names in this list (Active = Yes) appear in "Billed by" on the Bill screen.');
    }
    if (key === 'setup') {
      sh.getRange('B:B').setNumberFormat('@'); sh.setColumnWidth(1, 280); sh.setColumnWidth(2, 520); sh.setColumnWidth(3, 420);
      sh.getRange(2, 1, BILL_SETUP_DEFAULTS.length, 3).setValues(BILL_SETUP_DEFAULTS.map(r => [r[0], String(r[1]), r[2]]));
    }
  }
  return sh;
}
function brows_(key) {
  const sh = btab_(key), n = sh.getLastRow() - 1;
  return n < 1 ? [] : sh.getRange(2, 1, n, BH[key].length).getValues();
}
function billSetup_() {
  const c = CacheService.getScriptCache(), hit = c.get('billsetup');
  if (hit) return JSON.parse(hit);
  const sh = btab_('setup');
  const o = {};
  BILL_SETUP_DEFAULTS.forEach(r => o[r[0]] = String(r[1]));
  const have = {};
  if (sh.getLastRow() > 1) sh.getRange(2, 1, sh.getLastRow() - 1, 2).getValues().forEach(r => { if (r[0]) { o[String(r[0])] = String(r[1]); have[String(r[0])] = 1; } });
  const add = BILL_SETUP_DEFAULTS.filter(r => !have[r[0]]);
  if (add.length && sh.getLastRow() > 1) sh.getRange(sh.getLastRow() + 1, 1, add.length, 3).setValues(add.map(r => [r[0], String(r[1]), r[2]]));
  c.put('billsetup', JSON.stringify(o), 300);
  return o;
}
function locInfo_(setup, loc) {
  return { name: loc, series: s_(setup[loc + ' | Series']).toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 5) || 'BIL',
    address: s_(setup[loc + ' | Address']), fssai: s_(setup[loc + ' | FSSAI']) };
}
/** What the bill screen needs: seller details, locations, today's bills for a location. */
function billBoot_(d, user) {
  const st = billSetup_();
  const scope = billScope_(user);
  const locs = BILL_LOCS.filter(l => inScope_(scope, l)).map(l => locInfo_(st, l));
  return Object.assign({ setup: st, locs: locs, url: ScriptApp.getService().getUrl(), fy: fy_(new Date()), role: user.role,
    disc: { self: DISC_SELF, max: DISC_MAX, round: roundMax_() }, upiCheck: upiOn_(), gcOn: gcMode_() !== 'Off',
    allStores: !scope, otherLocs: scope ? BILL_LOCS.filter(l => l !== BILL_EVENT && scope.indexOf(l) < 0) : [], covering: scope ? accessToday_(user) : [], ref: refRules_(), lucky: luckyRules_(),
    today: d && d.loc && inScope_(scope, d.loc) ? listBills_({ date: ymd_(new Date()), loc: d.loc }, user) : null }, billLists_(), ownerLists_(user));
}
/** Master lists kept by the owner: open events and active staff names. */
function billLists_() {
  const events = brows_('events').filter(r => s_(r[0]) && s_(r[4]) !== 'Closed')
    .map(r => ({ name: s_(r[0]), venue: s_(r[1]), from: ymd_(r[2]), to: ymd_(r[3]), status: s_(r[4]) || 'Open' }));
  const staff = userRows_().map(x => userObj_(x.r)).filter(u => u.active && u.rights.indexOf('bill') >= 0).map(u => u.name);
  return { events: events, staff: staff, wa: { on: waReady_() }, listsAt: new Date().toISOString() };
}
/** Owner: replace the event list and/or staff list. d = {events:[{name, venue, from, to, status}], staff:[{name, active}]} */
function saveBillLists_(d) {
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    if (Array.isArray(d.events)) {
      const old = {}; brows_('events').forEach(r => old[norm_(r[0])] = s_(r[5]));
      const seen = {}, rows = [];
      d.events.forEach(e => {
        const nm = txt_(e.name, 100); if (!nm || seen[norm_(nm)]) return; seen[norm_(nm)] = 1;
        rows.push([nm, txt_(e.venue, 250), /^\d{4}-\d{2}-\d{2}$/.test(e.from || '') ? e.from : '', /^\d{4}-\d{2}-\d{2}$/.test(e.to || '') ? e.to : '',
          e.status === 'Closed' ? 'Closed' : 'Open', old[norm_(nm)] || '']);
      });
      const sh = btab_('events'); const n = sh.getLastRow() - 1;
      if (n > 0) sh.getRange(2, 1, n, BH.events.length).clearContent();
      if (rows.length) sh.getRange(2, 1, rows.length, BH.events.length).setValues(rows);
    }
    if (Array.isArray(d.staff)) {
      const seen = {}, rows = [];
      const notes = {}; brows_('staff').forEach(r => notes[norm_(r[0])] = s_(r[2]));
      d.staff.forEach(p => { const nm = txt_(p.name, 60); if (!nm || seen[norm_(nm)]) return; seen[norm_(nm)] = 1; rows.push([nm, p.active === 'No' ? 'No' : 'Yes', notes[norm_(nm)] || '']); });
      const sh = btab_('staff'); const n = sh.getLastRow() - 1;
      if (n > 0) sh.getRange(2, 1, n, BH.staff.length).clearContent();
      if (rows.length) sh.getRange(2, 1, rows.length, BH.staff.length).setValues(rows);
    }
  } finally { lock.releaseLock(); }
  return billLists_();
}
/** Owner extras: every event (open + closed) and every staff name, for Bill setup. */
function ownerLists_(user) {
  if (!can_(user, 'events')) return {};
  return { allEvents: allBillEvents_(), allStaff: brows_('staff').filter(r => s_(r[0])).map(r => ({ name: s_(r[0]), active: s_(r[1]) || 'Yes' })) };
}
/** Owner: add one event (or re-open it if the name already exists). d = {name, venue, from, to} */
function addBillEvent_(d, user) {
  const nm = txt_(d.name, 100);
