// ───────────────────────────── calculation (same code as billCalc in Billing.html) ─────────────────────────────
/**
 * lines: [{qty, rate, discPct, gst}] – rate is the selling price INCLUDING GST per unit.
 * billDisc: ₹ discount on the whole bill (shared across lines by value, before tax).
 * inter: true = IGST (customer GSTIN of another state), else CGST + SGST.
 */
function billCalc_(lines, billDisc, inter) {
  const r2 = x => Math.round((Number(x) || 0) * 100 + 1e-9) / 100;
  const out = lines.map(l => {
    const qty = Math.round((Number(l.qty) || 0) * 1000) / 1000, rate = r2(l.rate);
    const gross = r2(qty * rate);
    const ld = r2(gross * Math.min(Math.max(Number(l.discPct) || 0, 0), 100) / 100);
    return { qty: qty, rate: rate, gross: gross, disc: ld, gst: Number(l.gst) || 0 };
  });
  const afterLine = out.reduce((a, l) => a + (l.gross - l.disc), 0);
  let bd = Math.min(r2(billDisc), r2(afterLine));
  if (bd > 0 && afterLine > 0) {
    let left = bd;
    out.forEach((l, i) => {
      const base = l.gross - l.disc;
      const share = i === out.length - 1 ? r2(left) : r2(bd * base / afterLine);
      const s = Math.min(share, r2(base)); l.disc = r2(l.disc + s); left = r2(left - s);
    });
  }
  const t = { gross: 0, disc: 0, amount: 0, taxable: 0, cgst: 0, sgst: 0, igst: 0, qty: 0, rates: {} };
  out.forEach(l => {
    l.amount = r2(l.gross - l.disc);
    l.taxable = r2(l.amount * 100 / (100 + l.gst));
    const tax = r2(l.amount - l.taxable);
    if (inter) { l.igst = tax; l.cgst = 0; l.sgst = 0; } else { l.cgst = r2(tax / 2); l.sgst = r2(tax - l.cgst); l.igst = 0; }
    ['gross', 'disc', 'amount', 'taxable'].forEach(k => t[k] = r2(t[k] + l[k]));
    t.qty = Math.round((t.qty + l.qty) * 1000) / 1000;
    const k = String(l.gst); const g = t.rates[k] = t.rates[k] || { amount: 0, taxable: 0, cgst: 0, sgst: 0, igst: 0 };
    g.amount = r2(g.amount + l.amount); g.taxable = r2(g.taxable + l.taxable);
  });
  Object.keys(t.rates).forEach(k => {          // tax split per rate on the bill total, so CGST = SGST (± 1 paisa)
    const g = t.rates[k], tax = r2(g.amount - g.taxable);
    if (inter) g.igst = tax; else { g.cgst = r2(tax / 2); g.sgst = r2(tax - g.cgst); }
    t.cgst = r2(t.cgst + g.cgst); t.sgst = r2(t.sgst + g.sgst); t.igst = r2(t.igst + g.igst);
  });
  t.total = Math.round(t.amount);
  t.roundOff = r2(t.total - t.amount);
  return { lines: out, totals: t };
}

