      round2_(tot - tax), round2_(tax / 2), round2_(tax / 2), 0, tot, s_(r[PSC['Payment']]), n_(r[PSC['Cash ₹']]), n_(r[PSC['UPI ₹']]), n_(r[PSC['Card ₹']]), memo ? 'Handwritten memo' : who + ' (QB)']);
    if (st !== 'Sale') { if (st === 'Also billed in app') T.qb.also++; return; }
    const o = { bills: 1, total: tot, cash: n_(r[PSC['Cash ₹']]), upi: n_(r[PSC['UPI ₹']]), card: n_(r[PSC['Card ₹']]), other: n_(r[PSC['Other ₹']]) };
