  if (!r) return { ok: false, msg: 'No customer with this code / mobile. Check it, or leave it blank.' };
  if (s_(r[CUC['Phone']]) === selfPhone) return { ok: false, msg: 'A customer cannot refer themselves.' };
  const name = s_(r[CUC['Name']]), p = s_(r[CUC['Phone']]);
  return { ok: true, code: s_(r[CUC['Ref code']]), phone: p, name: name, label: (name || 'Customer') + ' · ' + p.slice(0, 2) + '••••' + p.slice(-4) };
