  if (s_(r[CPC['Phone']]) !== phone) throw new Error('Coupon ' + code + ' belongs to another customer (mobile must match).');
  if (/^LD/.test(code) && ymd_(r[CPC['Issued at']]) >= ymd_(new Date())) throw new Error('Lucky draw coupons can be used from the next visit (tomorrow onwards).');
  if (gross < n_(r[CPC['Min bill ₹']])) throw new Error('This coupon needs a bill of ₹' + n_(r[CPC['Min bill ₹']]) + ' or more (now ₹' + gross + ').');
  if (n_(d.billDisc) > 0 || (d.lines || []).some(l => n_(l.discPct) > 0)) throw new Error('A coupon cannot be combined with another discount – remove the other discount.');
