    if (s_(r[CPC['Earned from bill']]) === no && s_(r[CPC['Status']]) === 'Active') cs.getRange(i + 2, CPC['Status'] + 1).setValue('Void (bill ' + no + ' cancelled)');
    if (s_(r[CPC['Used on bill']]) === no && s_(r[CPC['Status']]) === 'Used') cs.getRange(i + 2, CPC['Status'] + 1, 1, 4).setValues([['Active', '', '', 'Bill ' + no + ' cancelled – usable again']]);
  });
  if (!phone) return;
  const sh = xtab_(CU_TAB, CU_H), rows = custRows_(), i = rows.findIndex(r => s_(r[CUC['Phone']]) === phone);
  if (i < 0) return;
