  const cpState = {}; cps.forEach(r => { const s = couponState_(r).replace(/ \(.*/, ''); cpState[s] = (cpState[s] || 0) + 1; });
  const mask = p => user.role === 'Owner' || can_(user, 'allStores') ? p : p.slice(0, 2) + '••••' + p.slice(-4);
  const cuObj = r => ({ phone: mask(s_(r[CUC['Phone']])), name: s_(r[CUC['Name']]), code: s_(r[CUC['Ref code']]), bills: n_(r[CUC['Bills']]), spent: n_(r[CUC['Total spent ₹']]),
    last: ymd_(r[CUC['Last bill date']]), referredBy: s_(r[CUC['Referred by code']]), status: s_(r[CUC['Referral status']]), referred: (refs[s_(r[CUC['Phone']])] || []).length });
  const top = Object.keys(refs).map(p => cus.find(r => s_(r[CUC['Phone']]) === p)).filter(Boolean).map(cuObj).sort((a, b) => b.referred - a.referred).slice(0, 20);
  const found = q ? cus.filter(r => norm_(r[CUC['Phone']] + ' ' + r[CUC['Name']] + ' ' + r[CUC['Ref code']]).indexOf(q) >= 0).slice(0, 30).map(cuObj) : [];
  const coupons = cps.slice(-60).reverse().map(r => ({ code: s_(r[0]), name: s_(r[CPC['Name']]), phone: mask(s_(r[CPC['Phone']])), pct: n_(r[CPC['Percent']]), issued: ymd_(r[CPC['Issued at']]),
    till: ymd_(r[CPC['Valid till']]), from: s_(r[CPC['Earned from customer']]).replace(/\d{6}(\d{4})$/, '••••$1'), status: couponState_(r), usedOn: s_(r[CPC['Used on bill']]) }));
  const ld = cps.filter(r => /^LD/.test(s_(r[0])));
  const lucky = { issued: ld.length, p10: ld.filter(r => n_(r[CPC['Percent']]) === 10).length, used: ld.filter(r => couponState_(r) === 'Used').length };
  return { rules: refRules_(), lucky: lucky, luckyRules: luckyRules_(), stats: { customers: cus.length, referred: cus.filter(r => s_(r[CUC['Referred by phone']])).length,
    rewarded: cus.filter(r => s_(r[CUC['Referral status']]) === 'Coupon issued').length, coupons: cpState }, top: top, found: found, coupons: coupons };
}


// ───────────────────────────── customer list (v18.9) ─────────────────────────────
