// ───────────────────────────── lucky draw (v9) ─────────────────────────────
// Store bill of ₹1,000+ with the customer's mobile → after saving, the customer picks one of three cards on the staff phone.
// The server decides the prize (5% or 10%), so it cannot be repeated or chosen by staff. The coupon (LD…) is tied to the mobile,
// usable from the next visit (tomorrow) for 30 days on a bill of ₹1,000+, one per bill, not combined with other discounts.
function luckyRules_() {
  return { min: num_('Lucky draw: bill of at least ₹', 1000), p10: Math.min(100, Math.max(0, num_('Lucky draw: chance of 10% coupon (out of 100)', 25))),
    days: num_('Lucky draw: coupon valid (days)', 30), use: num_('Lucky draw: coupon needs bill of ₹', 1000) };
}
function luckyOf_(no) {
  const r = xrows_(CP_TAB, CP_H).find(x => /^LD/.test(s_(x[0])) && s_(x[CPC['Earned from bill']]) === no);
  return r ? { code: s_(r[0]), pct: n_(r[CPC['Percent']]), till: ymd_(r[CPC['Valid till']]), use: n_(r[CPC['Min bill ₹']]), status: couponState_(r) } : null;
}
function withLucky_(b) { if (b) b.lucky = luckyOf_(b.no); return b; }
function luckyDraw_(d, user) {
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    const b = billInScope_(getBillByNo_(d.no), user), L = luckyRules_();
    if (b.status === 'Cancelled') throw new Error('This bill is cancelled.');
    if (b.loc === BILL_EVENT) throw new Error('The lucky draw is for store bills only.');
    if (!b.customer.phone) throw new Error('The lucky draw needs the customer\'s mobile number on the bill.');
    if (b.totals.total < L.min) throw new Error('The lucky draw needs a bill of ₹' + L.min + ' or more.');
    if (b.date !== ymd_(new Date())) throw new Error('The lucky draw can only be done on the day of the bill.');
    const had = luckyOf_(b.no); if (had) return Object.assign(had, { again: true });
    const pct = Math.random() * 100 < L.p10 ? 10 : 5, now = new Date();
    const taken = {}; xrows_(CP_TAB, CP_H).forEach(x => taken[s_(x[0])] = 1);
    const code = newCode_('LD', taken), till = new Date(now.getFullYear(), now.getMonth(), now.getDate() + L.days, 23, 59, 59);
    xtab_(CP_TAB, CP_H).appendRow([code, b.customer.phone, b.customer.name || '', pct, L.use, now, till, b.no, 'Lucky draw on bill ' + b.no, 'Active', '', '', 'Drawn by ' + user.name]);
    return { code: code, pct: pct, till: ymd_(till), use: L.use, status: 'Active' };
  } finally { lock.releaseLock(); }
}

// ───────────────────────────── WhatsApp Cloud API (automatic bills / coupons from the company number) ─────────────────────────────
/* Settings live in Script Properties (owner screen: Bill setup → WhatsApp auto). The access token is never sent to any phone.
