  bill: { name: 'nv_bill', category: 'UTILITY', header: 'DOCUMENT',
    body: 'Hi {{1}}, thank you for shopping at Nutvique {{2}}. Your bill {{3}} for ₹{{4}} is attached.',
    ex: ['Rahul', 'Gulshan One29 Mall', 'GUL/26-27/00012', '2,450.00'], footer: 'Nutzy Foods Pvt Ltd' },
  lucky: { name: 'nv_lucky', category: 'UTILITY',
