  ref: { name: 'nv_referral', category: 'UTILITY',
    body: 'Hi {{1}}, thank you for referring {{2}} to Nutvique! You have earned a {{3}}% off coupon: {{4}}. Use it on a purchase of ₹{{5}} or more at any Nutvique store, valid till {{6}}. Just share your mobile number at billing.',
    ex: ['Rahul', 'Priya', '10', 'CP4HX9T', '1,000', '20-11-2026'], footer: 'Nutzy Foods Pvt Ltd' }
