  const c = waCfg_();
  return { on: c.on, ready: !!(c.on && c.tok && c.pid), hasToken: !!c.tok, pid: c.pid, waba: c.waba, app: c.app, lang: c.lang,
    templates: Object.keys(WA_TPL).map(k => ({ key: k, name: WA_TPL[k].name, body: WA_TPL[k].body, header: WA_TPL[k].header || '', footer: WA_TPL[k].footer })) };
}
function waOwner_(user) { if (!user || user.role !== 'Owner') throw new Error('Only the owner can change WhatsApp settings.'); }
function waFetch_(path, opt, c) {
