  const have = {}; xrows_(BK_TAB, BK_H).forEach(r => have[s_(r[0])] = 1);
  const haveC = {}; xrows_(CS_TAB, CS_H).forEach(r => haveC[s_(r[0])] = 1);
  const now = new Date(), add = [], addC = [], term = bkTerminals_();
  const msgs = q => { const a = []; GmailApp.search(q, 0, 30).forEach(th => th.getMessages().forEach(m => { if (!seen[m.getId()]) a.push(m); })); return a; };
