        else if (cr > 0 && /^EZY\/ICICIPOS_SET/i.test(nar)) { src = 'ICICI card (net, info)'; sd = bkPrev_(on); amt = cr; }
        else if (dr > 0 && /MDRCC/i.test(nar)) { src = 'ICICI UPI charges'; sd = bkPrev_(on); amt = -dr; }
