}
/** Ticks each card bill that appears in the ICICI merchant statement (same store, day and amount). */
function bkMatchCards_() {
  const sh = xtab_(CS_TAB, CS_H), rows = xrows_(CS_TAB, CS_H), used = {};
  rows.forEach(r => { if (s_(r[12])) used[s_(r[12])] = 1; });
  const bills = brows_('bills').filter(r => s_(r[BC['Status']]) !== 'Cancelled' && n_(r[BC['Card ₹']]) > 0)
    .map(r => ({ no: s_(r[BC['Bill no.']]), date: ymd_(r[BC['Date']]), loc: s_(r[BC['Location']]), card: n_(r[BC['Card ₹']]) }));
  rows.forEach((r, i) => {
    if (s_(r[12])) return;
    const b = bills.find(x => !used[x.no] && x.date === ymd_(r[2]) && Math.abs(x.card - n_(r[7])) < 0.5 && (!s_(r[5]) || x.loc === s_(r[5])));
    if (b) { used[b.no] = 1; sh.getRange(i + 2, 13).setValue(b.no); }
  });
}
/** d = {from, to, scan} → one row per sales day. */
function bankTally_(d, user) {
  if (user.role !== 'Owner' && !can_(user, 'sales')) throw new Error('Only the owner or people with the Sales report right can see the bank tally.');
  let scan = null; try { scan = bkScan_(!!d.scan); } catch (e) { scan = { errors: [e.message] }; }
  const today = ymd_(new Date()), to = /^\d{4}-\d{2}-\d{2}$/.test(d.to || '') ? d.to : bkPrev_(today);
  const from = /^\d{4}-\d{2}-\d{2}$/.test(d.from || '') ? d.from : (() => { const x = new Date(to + 'T12:00:00Z'); x.setUTCDate(x.getUTCDate() - 13); return x.toISOString().slice(0, 10); })();
  const days = {}, day = k => days[k] = days[k] || { date: k, upi: 0, card: 0, byLoc: {}, icUpi: 0, paytm: 0, mdr: 0, cardGross: 0, cardCharges: 0, cardNet: 0, cardInfo: 0, cardTx: [], credits: [] };
  const addLoc = (k, loc, upi, card) => { const x = day(k); x.upi = round2_(x.upi + upi); x.card = round2_(x.card + card); const l = x.byLoc[loc] = x.byLoc[loc] || { upi: 0, card: 0 }; l.upi = round2_(l.upi + upi); l.card = round2_(l.card + card); };
  brows_('bills').forEach(r => { const k = ymd_(r[BC['Date']]); if (k < from || k > to || s_(r[BC['Status']]) === 'Cancelled') return; addLoc(k, s_(r[BC['Location']]), n_(r[BC['UPI ₹']]), n_(r[BC['Card ₹']])); });
  const ps = book_().getSheetByName(PS_TAB);
  if (ps && ps.getLastRow() > 1) ps.getRange(2, 1, ps.getLastRow() - 1, PS_H.length).getValues().forEach(r => { const k = ymd_(r[2]) || s_(r[2]); if (k < from || k > to || s_(r[16]) !== 'Sale') return; addLoc(k, s_(r[4]), n_(r[12]), n_(r[13])); });
  xrows_(BK_TAB, BK_H).forEach(r => { const k = ymd_(r[2]) || s_(r[2]); if (k < from || k > to) return; const x = day(k), a = n_(r[4]), s = s_(r[3]);
    if (s === 'Paytm') x.paytm = round2_(x.paytm + a); else if (s === 'ICICI UPI QR') x.icUpi = round2_(x.icUpi + a); else if (s === 'ICICI UPI charges') x.mdr = round2_(x.mdr - a); else x.cardInfo = round2_(x.cardInfo + a);
    x.credits.push({ on: ymd_(r[1]), src: s, amount: a }); });
  xrows_(CS_TAB, CS_H).forEach(r => { const k = ymd_(r[2]) || s_(r[2]); if (k < from || k > to) return; const x = day(k);
    x.cardGross = round2_(x.cardGross + n_(r[7])); x.cardCharges = round2_(x.cardCharges - n_(r[8]) - n_(r[9])); x.cardNet = round2_(x.cardNet + n_(r[10]));
    x.cardTx.push({ time: s_(r[3]), loc: s_(r[5]) || s_(r[4]), amount: n_(r[7]), net: n_(r[10]), card: s_(r[11]), bill: s_(r[12]) }); });
  const chk = {}; xrows_(BTL_TAB, BTL_H).forEach(r => chk[ymd_(r[0]) || s_(r[0])] = { status: s_(r[1]), by: s_(r[2]), at: iso_(r[3]), note: s_(r[4]) });
  const last = PropertiesService.getScriptProperties().getProperty('BK_LAST') || '';
  const list = Object.values(days).filter(x => x.date >= from && x.date <= to).sort((a, b) => a.date < b.date ? 1 : -1).map(x => {
    const sold = round2_(x.upi + x.card), got = round2_(x.icUpi + x.paytm + x.cardGross), diff = round2_(got - sold), anyBank = x.credits.length + x.cardTx.length > 0;
    const tol = Math.max(5, round2_(x.paytm * 0.025));
    const status = chk[x.date] && chk[x.date].status === 'Checked' ? 'Checked' : !anyBank ? (sold ? 'Waiting for bank' : 'No UPI / card') : Math.abs(diff) <= tol ? 'Tallied' : 'Difference';
