  });
  return { from: from, to: to, list: list, lastRead: last, scan: scan, canCheck: user.role === 'Owner',
    totals: { sold: round2_(list.reduce((a, x) => a + x.sold, 0)), received: round2_(list.reduce((a, x) => a + x.received, 0)) } };
